    S.l(M.barrel.base, 27.0, 0, 35.4, 0);                    // 裸露枪管 → cols 27-35 / 行 0
    S.l(M.phosphate.base, 20.6, -1, 28.4, -1);               // 导气管（枪管上方那条）
    S.r(M.phosphate, 29.6, -2, 1.0, 1);                      // 前准星座 → col 30 / 行 -2
    S.r(M.barrel, 33.6, -1, 1.8, 2);                         // 消焰器 → cols 34,35 / 行 -1..0
    S.l(M.blued.lo, 34.2, -0.6, 34.2, 0.4, true);            // 焰器槽
