  // ---------- 81 式自动步枪：长行程导气 + 机匣上方提把 + 固定聚合物托 ----------
  // 实测：托顶贴行 -1、底由 +3.7 抬到 +1.2 的长楔（cols 0-7）；握把 cols 8-11 下到行 4；
  //   提把 cols 11-15 顶到行 -2（底下是空的）；弹匣 cols 14-17 强弧、最深行 6；
  //   护木 cols 17-23（-1.12→+0.95）；导气箍与前准星 cols 24-26；裸露枪管 cols 27-31（Ø0.6）
  const type81Body = (S) => {
    S.r(M.polyDark, 0.0, -1, 2.6, 4);                        // 托尾 → cols 0-2 / 行 -1..2
    S.r(M.polyDark, 2.6, -1, 2.0, 3);                        // 托中 → cols 3,4 / 行 -1..1
    S.r(M.polyDark, 4.6, -1, 3.0, 2);                        // 托前 → cols 5-7 / 行 -1..0
    S.l(M.poly.hi, 0.4, -0.4, 6.4, -0.4, true);              // 贴腮线
    S.d(M.polyDark.edge, 1.0, 2.4, 1, true);                 // 背带环座
    S.r(M.parkerized, 7.6, -1, 9.6, 2);                      // 机匣 → cols 8-16 / 行 -1..0
    S.r(M.phosphate, 10.6, -2, 4.6, 1);                      // 提把横梁 → cols 11-15 / 行 -2
    S.l(M.blued.lo, 11.4, -1.2, 14.6, -1.2, true);           // 提把下沿（与机匣盖之间那道缝）
    S.r(M.polyDark, 7.6, 1, 2.6, 3);                         // 握把 → cols 8-10 / 行 1..3
    S.r(M.polyDark, 10.6, 1, 1.0, 2);                        // 握把前缘 → col 11 / 行 1..2
    S.r(M.polyDark, 8.6, 4, 1.0, 1);                         // 握把底 → col 9 / 行 4
    for (let i = 0; i < 3; i++) S.d(M.poly.lo, 7.8 + i * 0.8, 1.6 + i * 0.8, 1, true);   // 指槽
    S.r(M.polyDark, 13.6, 1, 2.6, 4);                        // 弹匣上中段（7.62×39 强弧）→ cols 14-16 / 行 1..4
    S.r(M.polyDark, 14.6, 5, 1.6, 1);                        // 弹匣下段 → col 15 / 行 5
    S.r(M.polyDark, 14.6, 6, 1.0, 1);                        // 弹匣底板 → col 15 / 行 6
    for (let i = 0; i < 2; i++) S.l(M.polyDark.edge, 14.0 + i * 0.9, 1.4, 14.6 + i * 0.9, 4.2, true);   // 匣身加强筋
    S.l(M.phosphate.hi, 12.8, 1.4, 13.2, 1.4);               // 扳机护圈前柱 → col 13 / 行 1
    S.l(M.phosphate.hi, 11.8, 2.4, 12.2, 2.4);               // 扳机护圈底 → col 12 / 行 2
    S.l(M.barrel.hi, 11.4, 0.6, 11.2, 1.0, true);            // 扳机（落在 col 11，护圈洞在 col 12）
    S.r(M.poly, 16.6, -1, 7.0, 2);                           // 护木 → cols 17-23 / 行 -1..0
    for (let i = 0; i < 4; i++) S.l(M.polyDark.lo, 17.4 + i * 1.5, -0.8, 17.4 + i * 1.5, 0.4);          // 护木竖肋（战斗尺度）
    S.r(M.poly, 23.6, -1, 3.0, 1);                           // 导气箍 + 准星座 → cols 24-26 / 行 -1
    S.l(M.blued.lo, 24.2, -0.8, 25.8, -0.8, true);           // 准星护翼
    S.l(M.barrel.base, 26.6, 0, 31.4, 0);                    // 裸露枪管 → cols 27-31 / 行 0
    S.l(M.barrel.edge, 30.4, -1, 31.4, -1);                  // 消焰器上棱 → cols 30,31 / 行 -1
    S.l(M.blued.lo, 30.8, -0.6, 30.8, 0.4, true);            // 焰器槽
  };
  const type81Silhouette = 单向('type81', type81Body);

  // ---------- QBZ-191：短行程活塞 + 平顶导轨 + 伸缩托 ----------
  // 实测：伸缩托 cols 0-6（顶在行 0、底由 +4.0 抬到 +1.5，托尾带空腔）；机匣 cols 7-25 rows -1..0；
  //   瞄具 cols 9,10 顶到行 -2；握把 cols 7-9 下到行 4；弹匣 cols 13-17 下到行 6；
  //   护木 cols 17-23（-1.33→+0.86，冲切导轨窗）；折叠前准星 col 24 顶到行 -3；裸露枪管 cols 25-31
  const qbz191Body = (S) => {
    S.r(M.polyDark, 0.0, 0, 1.0, 5);                         // 托底板 → col 0 / 行 0..4
    S.r(M.polyDark, 1.0, 0, 1.6, 4);                         // 托后 → cols 1,2 / 行 0..3
    S.r(M.polyDark, 2.6, 0, 1.0, 3);                         // 托中 → col 3 / 行 0..2
    S.r(M.polyDark, 3.6, 0, 1.0, 3);                         // 托前中 → col 4 / 行 0..2
    S.r(M.polyDark, 4.6, 0, 1.6, 2);                         // 托颈 → cols 5,6 / 行 0..1
    S.l(M.polyDark.lo, 0.8, 2.4, 3.4, 2.4, true);            // 托身减重槽
    S.d(M.polyDark.edge, 4.2, 0.4, 1, true);                 // 伸缩档位钮
    S.r(M.parkerized, 6.6, -1, 19.0, 1);                      // 机匣上沿 → cols 7-25 / 行 -1
    S.r(M.parkerized, 6.6, 0, 18.0, 1);                       // 机匣下沿 → cols 7-24 / 行 0（col 25 是准星座下的空档）
    S.r(M.blued, 8.6, -2, 2.0, 1);                           // 光学瞄具 → cols 9,10 / 行 -2
    S.l(M.glass.base, 9.0, -1.6, 10.4, -1.6, true);          // 镜片
    S.r(M.polyDark, 7.6, 1, 2.0, 4);                         // 握把 → cols 8,9 / 行 1..4
    for (let i = 0; i < 2; i++) S.d(M.poly.lo, 7.8 + i * 0.8, 2.4 + i * 0.8, 1, true);   // 指槽
    S.r(M.parkerized, 9.6, 1, 3.6, 1);                       // 弹匣井 → cols 10-12 / 行 1（护圈洞在 cols 11,12 行 2）
    S.r(M.polyDark, 13.6, 1, 2.6, 4);                        // 弹匣（5.8 强弧）→ cols 14-16 / 行 1..4
    S.r(M.polyDark, 14.6, 5, 1.6, 1);                        // 弹匣下段 → cols 15,16 / 行 5
    S.r(M.polyDark, 9.6, 2, 1.0, 2);                         // 弹匣后上角 → col 10 / 行 2..3
    S.r(M.polyDark, 12.6, 2, 1.0, 1);                        // → col 13 / 行 2
    S.r(M.parkerized, 16.6, 1, 1.4, 1);                      // 弹匣井前壁 → col 17 / 行 1
    S.r(M.polyDark, 14.6, 6, 1.0, 1);                        // 弹匣底板 → col 15 / 行 6
    for (let i = 0; i < 2; i++) S.l(M.polyDark.edge, 14.0 + i * 0.9, 1.4, 14.6 + i * 0.9, 5.2, true);   // 匣身纵筋
    S.l(M.phosphate.hi, 12.4, 1.4, 13.6, 1.4, true);         // 扳机护圈
    S.l(M.barrel.hi, 12.9, 0.6, 12.7, 1.0, true);            // 扳机
    S.r(M.poly, 16.6, -1, 7.0, 2);                           // 护木 → cols 17-23 / 行 -1..0
    for (let i = 0; i < 3; i++) S.l(M.polyDark.lo, 17.6 + i * 2.0, -0.8, 18.8 + i * 2.0, -0.8);         // 冲切导轨窗（战斗尺度）
    S.r(M.phosphate, 23.6, -3, 1.0, 2);                      // 折叠前准星 → col 24 / 行 -3..-2
    S.l(M.barrel.base, 25.6, 0, 31.4, 0);                    // 裸露枪管 → cols 26-31 / 行 0
    S.l(M.barrel.edge, 29.4, -1, 31.4, -1);                  // 消焰器上棱 → cols 29-31 / 行 -1
    S.l(M.blued.lo, 30.0, -0.6, 30.0, 0.4, true);            // 焰器槽
  };
  const qbz191Silhouette = 单向('qbz191', qbz191Body);

  // ---------- QBZ-95：无托 + 机匣上方一体式提把 ----------
  // 实测：整块聚合物机匣 cols 0-20 rows -1..0（托机匣不分家）；
  //   提把 cols 9-15 顶到行 -2；弹匣 cols 5-8 下到行 5（无托：弹匣在握把**之后**、贴近托尾）；
  //   握把 cols 10-12 下到行 4；护圈 cols 15-17 行 1 是空的；折叠前准星 col 20 顶到行 -3；
  //   裸露枪管 cols 21-24（Ø0.5）
  const qbz95Body = (S) => {
    S.r(M.poly, 0.0, -1, 20.6, 1);                           // 机匣+托一体上沿 → cols 0-20 / 行 -1
    S.r(M.poly, 0.0, 0, 19.6, 1);                            // 机匣+托一体下沿 → cols 0-19 / 行 0
    S.r(M.poly, 0.0, 1, 1.6, 2);                             // 机匣下沿后段 → cols 0,1 / 行 1..2
    S.r(M.poly, 1.6, 1, 3.0, 1);                             // → cols 2-4 / 行 1
    S.r(M.poly, 4.6, 1, 4.0, 2);                             // 机匣下沿中段 → cols 5-8 / 行 1..2
    S.r(M.poly, 9.6, 1, 2.6, 1);                             // 机匣下沿前段 → cols 10-12 / 行 1（cols 13-17 是护圈洞）
    S.l(M.poly.hi, 1.4, -0.6, 8.4, -0.6, true);              // 机匣侧腰线
    S.r(M.poly, 8.6, -2, 6.6, 1);                            // 一体式提把 → cols 9-15 / 行 -2
    S.l(M.blued.lo, 9.4, -1.2, 14.6, -1.2, true);            // 提把下沿的缝
    S.r(M.polyDark, 5.6, 1, 2.6, 4);                         // 弹匣（5.8 强弧，在握把之后）→ cols 6-8 / 行 1..4
    S.r(M.polyDark, 4.6, 2, 1.0, 1);                         // 弹匣后上角 → col 5 / 行 2
    S.r(M.polyDark, 5.6, 5, 1.0, 1);                         // 弹匣底板 → col 6 / 行 5
    for (let i = 0; i < 2; i++) S.l(M.polyDark.edge, 5.8 + i * 0.9, 1.4, 6.4 + i * 0.9, 4.2, true);     // 匣身纵筋
    S.r(M.polyDark, 10.6, 1, 1.6, 2);                        // 握把 → cols 11,12 / 行 1..2
    S.r(M.polyDark, 10.6, 3, 1.0, 2);                        // 握把底 → col 11 / 行 3..4
    for (let i = 0; i < 2; i++) S.d(M.poly.lo, 10.8 + i * 0.8, 1.6 + i * 0.8, 1, true);   // 指槽
    S.l(M.phosphate.hi, 12.4, 0.4, 14.6, 0.4, true);         // 扳机护圈上沿（洞在 cols 14-17 行 1）
    S.l(M.barrel.hi, 12.2, 0.6, 12.2, 1.0, true);            // 扳机（无托的长连杆）
    S.r(M.poly, 15.6, -1, 3.6, 2);                           // 护木 → cols 16-19 / 行 -1..0
    for (let i = 0; i < 2; i++) S.l(M.polyDark.lo, 16.4 + i * 2.2, -0.8, 17.2 + i * 2.2, -0.8);         // 护木散热槽
    S.r(M.phosphate, 19.6, -3, 1.0, 2);                      // 折叠前准星 → col 20 / 行 -3..-2
    S.l(M.barrel.base, 21.0, 0, 24.4, 0);                    // 裸露枪管 → cols 21-24 / 行 0
    S.l(M.barrel.edge, 22.6, -1, 24.2, -1);                  // 消焰器上棱 → cols 23,24 / 行 -1
    S.l(M.blued.lo, 23.2, -0.6, 23.2, 0.4, true);            // 焰器槽
    S.d(M.polyDark.edge, 13.4, -0.6, 1, true);               // 快慢机/保险轴（在机匣行 -1 内）
  };
  const qbz95Silhouette = 单向('qbz95', qbz95Body);

  // ============================================================
  // 批量第 4 批：AWM / M24 / 春田 M1903（各一张左视图，三支都是栓动狙击）
  // ------------------------------------------------------------
  // 同一把标尺 1 单位 = 29.4mm：AWM(1120mm .300 Win Mag)=38.1、M24 SWS(1112mm)=37.8、
  // M1903(1107mm)=37.7。三把在现实里几乎等长，画出来也几乎等长 —— 这是对的，
  // 它们的区分靠轮廓内部（拇指孔托 / 蒙特卡洛托 / 全木半手枪握托 + 瞄具位置），不靠长度。
  //
  // 标尺反查（三张图各自独立成立，不是把 len 硬凑出来的）：
  //   AWM  瞄具实测 13 格长 × 2 格高 = 382×59mm —— 正是 30mm 镜筒 + 物镜喇叭口的规格；
  //        全枪含瞄具高 6 格 = 176mm，与 AWM 带镜的实际总高 160~180mm 对得上。
  //   M24  裸露枪管 cols 25-37 上下缘 -0.26/+0.29 = 16mm，正是 M24 枪口处枪管直径。
  //   M1903 裸露枪管 cols 36-37 = -0.23/+0.26 = 14.4mm，正是春田枪口直径。
  //
  // 这一批额外做了一次"整格并集"采样（GUN_SAMPLE=cell）当对照：
  //   格心单点每格只取一个像素列，而一格 35px、准星座只有 15px 宽，有四成概率正好落在
  //   两个采样点之间被整个漏掉。对照跑出来 M1903 的枪口准星（cols 36-37 行 -1）、
  //   AWM 的物镜端（col 20）、M24 的瞄具前后环座（cols 7、19）都是格心采样漏掉的。
  //   建模目标取两次采样的**并集**；两侧不一致的那几格在下面逐条注明。
  //   唯一排除的是 awm(38,0)：那是墨迹最外缘 3 个像素落进第 38 格，而 len=38.1 的
  //   数学枪口尖本来就在 38.1 —— 与 m4a1 同一口径（画到 col 30、锚点在 30.6）。
  //
  // 瞄准镜是这三张参照图本体轮廓的一部分（照片里就装着镜），所以进造型；
  // 这与已经被收起的配件系统是两回事。
  // ============================================================

  // ---------- AWM：拇指孔枪托 + 一体式镜座，长枪管 ----------
  // 目标格（格心∪整格，共 109）：
  //   行 -2/-1：cols 8-20（瞄具）      行 0：cols 0-37（全长脊线）
  //   行 1：cols 0-6, 9-10, 12-24      行 2：cols 0-6, 9, 12-15
  //   行 3：cols 0-3, 5-9, 13-14
  //   洞（必须留空）：拇指孔 (7,1)(8,1)(7,2)(8,2)、护圈与腕部 (11,1)(10,2)(11,2)
  const awmBody = (S) => {
    // —— 行 0 脊线：托背 / 机匣 / 护木 / 裸露枪管 ——
    S.r(M.olive, 0, 0, 9.6, 1);                                 // 枪托上棱 → cols 0-9 / 行 0
    S.r(M.blued, 9.6, 0, 9.6, 1);                               // 机匣 → cols 10-19 / 行 0
    S.r(M.olive, 19.2, 0, 4.8, 1);                              // 前护木（橄榄绿）→ cols 19-23 / 行 0
    S.l(M.barrel.base, 24.4, 0, 37.4, 0);                       // 裸露枪管（1 行线，不描边）→ cols 24-37
    // —— 瞄具：整格采样比格心多出 col 20（物镜喇叭口），取并集到 8-20 ——
    S.r(M.polyDark, 8, -2, 13.0, 2);                            // 镜身 → cols 8-20 / 行 -2..-1
    S.l(M.glass.hi, 17.4, -1.6, 20.4, -1.6, true);              // 物镜镜片（检视）
    S.l(M.polyDark.lo, 8.4, -1.6, 11.4, -1.6, true);            // 目镜（检视）
    S.d(M.polyDark.edge, 13.4, -1.6, 1, true);                  // 高低转鼓（检视）
    // —— 托体：拇指孔两侧的肉 ——
    S.r(M.olive, 0, 1, 7.0, 1);                                 // 托身后段 → cols 0-6 / 行 1
    S.r(M.olive, 0, 2, 7.0, 1);                                 // 托身后段 → cols 0-6 / 行 2
    S.r(M.olive, 9, 1, 2.0, 1);                                 // 拇指孔与护圈之间的腕部 → cols 9,10 / 行 1
    S.r(M.olive, 9, 2, 1.0, 1);                                 // → col 9 / 行 2
    S.r(M.polyDark, 0, 3, 4.0, 1);                              // 橡胶托底板 → cols 0-3 / 行 3
    S.r(M.olive, 5, 3, 5.0, 1);                                 // 握把下方（孔洞下沿）→ cols 5-9 / 行 3
    S.d(M.olive.edge, 1.4, 2.4, 1, true);                       // 托身螺栓（检视）
    // —— 机匣下方：扳机区 + 弹匣 + 护木下沿 ——
    S.r(M.olive, 12, 1, 13.0, 1);                               // 护圈/托颈/护木下沿 → cols 12-24 / 行 1
    S.r(M.polyDark, 13, 2, 3.0, 1);                             // 弹匣 → cols 13-15 / 行 2
    // col 12 行 2 原来也画着：第 4 批那张 AWM 图的整格采样说那里有墨；
    // 后到的第二张 AWM 图在该格测到被围住的白，四个口径里三个说留空，故收窄一格。
    // 代价如实记：对第 4 批那张图的整格参照会显示"缺 1"（见第 8 批交付正文）。
    S.r(M.polyDark, 13, 3, 2.0, 1);                             // 弹匣底板 → cols 13,14 / 行 3
    S.l(M.blued.hi, 10.4, -0.4, 19.4, -0.4, true);              // 机匣拉栓槽（检视）
    S.d(M.blued.edge, 11.4, 0.4, 1, true);                      // 弹匣卡笋（检视）
    S.l(M.blued.lo, 35.4, -0.4, 35.4, 0.4, true);               // 制退器槽
    S.l(M.blued.lo, 36.6, -0.4, 36.6, 0.4, true);               // 制退器槽
  };
  const awmSilhouette = 单向('awm', awmBody);

  // ---------- M24 SWS：蒙特卡洛黑合成托 + 分体镜环 ----------
  // 目标格（格心∪整格，共 93）：
  //   行 -2：cols 7-19      行 -1：cols 7-11, 15-19（中间 cols 12-14 是镜筒与机匣之间的空档）
  //   行 0：cols 7-37       行 1：cols 0-8, 10-13, 19-24
  //   行 2：cols 0-8        行 3：cols 0-7        行 4：cols 0,1,3
  //   洞：托底与背带环之间 (2,4)、扳机护圈里 (9,1)(9,2)(10,2)(11,2)、镜下 (12,-1)(13,-1)(14,-1)
  //   注意 M24 的托顶整条都在膛轴之下（行 1 起），行 0 只有枪管与机匣 —— 与 AWM 不同。
  const m24Body = (S) => {
    S.r(M.phosphate, 7, 0, 18.0, 1);                            // 机匣 + 护木上棱 → cols 7-24 / 行 0
    S.l(M.barrel.base, 24.4, 0, 37.4, 0);                       // 裸露枪管 → cols 24-37 / 行 0
    // —— 瞄具：镜筒一行到底，镜环比镜筒低半格，所以行 -1 只在前后两处 ——
    S.r(M.polyDark, 7, -2, 13.0, 1);                            // 镜筒 → cols 7-19 / 行 -2
    S.r(M.polyDark, 7, -1, 5.0, 1);                             // 后镜环 → cols 7-11 / 行 -1
    S.r(M.polyDark, 15, -1, 5.0, 1);                            // 前镜环 → cols 15-19 / 行 -1
    S.l(M.glass.hi, 15.4, -1.6, 18.4, -1.6, true);              // 物镜（只在前段，整条都亮会读成一根蓝管）
    S.l(M.polyDark.lo, 7.4, -1.6, 10.4, -1.6, true);            // 目镜
    S.d(M.polyDark.edge, 12.4, -1.6, 1, true);                  // 转鼓
    // —— 黑合成托：整条在膛轴下方 ——
    S.r(M.poly, 0, 1, 9.0, 1);                                  // 托背上棱 → cols 0-8 / 行 1
    S.r(M.poly, 0, 2, 9.0, 1);                                  // 托身 → cols 0-8 / 行 2
    S.r(M.poly, 0, 3, 8.0, 1);                                  // 托身 → cols 0-7 / 行 3
    S.r(M.poly, 10, 1, 4.0, 1);                                 // 握把/护圈（整格采样多出 cols 11-13）→ cols 10-13 / 行 1
    S.r(M.poly, 19, 1, 6.0, 1);                                 // 护木下沿 → cols 19-24 / 行 1
    S.r(M.polyDark, 0, 4, 2.0, 1);                              // 托底板 → cols 0,1 / 行 4
    S.r(M.polyDark, 3, 4, 1.0, 1);                              // 背带环 → col 3 / 行 4
    S.l(M.poly.hi, 0.4, 1.4, 6.4, 1.4, true);                   // 贴腮线（检视）
    S.l(M.barrel.hi, 12.4, 0.4, 13.4, 1.4, true);               // 拉机柄（球头）→ (12,0)(13,1)
    S.l(M.barrel.hi, 11.4, 0.6, 11.4, 1.4, true);               // 扳机
    S.l(M.blued.lo, 36.4, -0.4, 36.4, 0.4, true);               // 消焰器槽
  };
  const m24Silhouette = 单向('m24', m24Body);

  // ---------- 春田 M1903：全木枪托包到枪口、带前准星与箍 ——
  // 目标格（格心∪整格，共 88）：
  //   行 -2/-1：cols 7-17（瞄具）+ cols 36-37（枪口准星，只有格心采样的话会被整格采样的
  //             上下缘同相位吃掉：那两格真实跨度 -0.86..+0.29 = 1.15 单位，取整只剩一行，
  //             格心说在行 0、整格说在行 -1 —— 两行都有墨，所以两行都画）
  //   行 0：cols 7-37     行 1：cols 0-9, 11-13, 18-19, 23-24
  //   行 2：cols 0-7      行 3：cols 0-4      行 4：cols 0,1,3
  //   洞：(2,4)(9,2)(10,1)
  const m1903Body = (S) => {
    S.r(M.blued, 7, 0, 11.0, 1);                                // 机匣 + 裸露上段 → cols 7-17 / 行 0
    S.r(M.walnut, 18, 0, 16.0, 1);                              // 全木上护木 → cols 18-33 / 行 0
    S.l(M.barrel.base, 34.4, 0, 37.4, 0);                       // 裸露枪管（护木之后）→ cols 34-37 / 行 0
    S.r(M.phosphate, 36, -1, 2.0, 1);                           // 枪口准星座 → cols 36,37 / 行 -1
    S.r(M.polyDark, 7, -2, 11.0, 2);                            // 瞄具 → cols 7-17 / 行 -2..-1
    S.l(M.glass.hi, 14.4, -1.6, 16.4, -1.6, true);              // 物镜（只在前段）
    S.l(M.polyDark.lo, 7.4, -1.6, 10.4, -1.6, true);            // 目镜
    S.d(M.polyDark.edge, 11.4, -1.6, 1, true);                  // 转鼓
    S.r(M.walnut, 0, 1, 10.0, 1);                               // 托背 → cols 0-9 / 行 1
    S.r(M.walnut, 0, 2, 8.0, 1);                                // 托身 → cols 0-7 / 行 2
    S.r(M.walnut, 0, 3, 5.0, 1);                                // 托身下部 → cols 0-4 / 行 3
    S.r(M.blued, 11, 1, 3.0, 1);                                // 扳机护圈（整格采样多出 cols 12,13）→ cols 11-13 / 行 1
    S.r(M.blued, 18, 1, 2.0, 1);                                // 前箍下沿 → cols 18,19 / 行 1
    S.r(M.blued, 23, 1, 2.0, 1);                                // 中段箍 + 背带环 → cols 23,24 / 行 1
    S.r(M.polyDark, 0, 4, 2.0, 1);                              // 钢托底板 → cols 0,1 / 行 4
    S.r(M.polyDark, 3, 4, 1.0, 1);                              // 背带环 → col 3 / 行 4
    S.l(M.wood.hi, 0.4, 1.4, 7.4, 1.4, true);                   // 木纹/贴腮线（检视）
    S.l(M.barrel.hi, 12.4, 0.4, 13.4, 1.4, true);               // 拉机柄（球头）→ (12,0)(13,1)
    S.d(M.barrel.hi, 18.4, -0.4, 1, true);                      // 箍环螺栓
  };
  const m1903Silhouette = 单向('m1903', m1903Body);

  // ============================================================
  // 批量第 5 批立项、第 9 批整份重建：SR-25 / MK12 / QBU-09（三支半自动精确射手步枪）
  // ------------------------------------------------------------
  // 第 5 批用的三张图后来全被换掉了：mk12 那张其实拍的是 SVD/85 式（当时用户指定"仍按标注建到 mk12"），
  // sr25 那张装着消音器、qbu09 那张是栓动 FDE 底盘。第 9 批拿到三张真正的 AR-10 系左视图后，
  // 三份轮廓全部按新图重画，旧格位一个都不留（旧版对新图只覆盖 68%~78%）。
  //
  // 同一把标尺 1 单位 = 29.4mm，len 取**该 ID 所对应型号**的公开全长，不取照片主体的全长：
  //   sr25   KAC SR-25 MWS 20" 枪管型 1060mm ⇒ 36.1（按此定标尺后，照片墨迹实读 1061mm）
  //   mk12   Mk 12 SPR 18" 型 1054mm        ⇒ 35.9（同上，实读 1055mm）
  //   qbu09  没有可靠公开全长 ⇒ 沿用第 5 批由照片自解出来的 38.0，不新造一个数。
  //          这条是**假设不是查证**：38.0 折回 1117mm，只能靠下面的独立件径来判它靠不靠谱。
  //
  // 三张图各自独立验过标尺（不是拿总长凑总长）：镜筒直径实测 27~34mm（标准 30~34mm 镜筒）、
  // 枪口段裸管直径 13~17mm（7.62 枪口段外径约 15mm），两个与总长无关的参照同时落在合理带内。
  // 复核命令：node 美术重构-工作区/工具/_gun_spec.js <id>（列出每块实绘件占几格、折回多少毫米）。
  //
  // 与第 4 批同一口径：建模目标 = 格心采样 ∪ 整格采样（后者专抓窄高件），
  // 三份都跑到 缺=0、填洞=0，且**没有多画的格**（设计格集与并集目标完全相等）。
  // ============================================================

  // ---------- SR-25（第 9 批改按 v2 参照图重建：黑色冲切护木 + ACS 伸缩托） ----------
  // 目标格（格心 ∪ 整格，并集 133 − 脚架腿 7 = 126）：
  //   行 -3：cols 8-11, 13,14, 17-20   行 -2：cols 8-20    行 -1：cols 0-6, 8-30
  //   行  0：cols 0-36                 行  1：cols 0-2, 4,5, 8-16
  //   行  2：cols 0-2, 8-10, 13-16     行  3：col 1, 8-10, 13-16     行  4：col 8, 13-15
  //   洞：托身调节槽 (3,1)(2,3)、护圈 (11,2)(12,2)
  //   第 5 批那版（红棕胡桃拇指孔托 + 消音器）已整份替换：用户后来给的 v2 图才是这轮的参照。
  const sr25Body = (S) => {
    // —— 行 0 脊线：托 → 机匣 → 护木 → 裸露枪管 → 消焰器 ——
    S.r(M.noir, 0, 0, 31.0, 1);                                // 托 + 机匣 + 护木 → cols 0-30 / 行 0
    S.l(M.barrel.base, 31.4, 0, 35.4, 0);                      // 裸露枪管 → cols 31-35 / 行 0
    S.r(M.barrel, 35.6, 0, 1.4, 1);                            // 消焰器 → col 36 / 行 0
    // —— 行 -1：托腮垫 + 全长平顶导轨（col 7 是托与导轨之间那道缝）——
    S.r(M.poly, 0, -1, 7.0, 1);                                // 托腮垫 → cols 0-6 / 行 -1
    S.r(M.noir, 8, -1, 23.0, 1);                               // 机匣顶 + 护木顶导轨 → cols 8-30 / 行 -1
    // —— 瞄具：镜身两行，行 -3 只有目镜端、转鼓、物镜端三坨 ——
    S.r(M.polyDark, 8, -2, 13.0, 1);                           // 镜身 → cols 8-20 / 行 -2
    S.r(M.polyDark, 8, -3, 4.0, 1);                            // 目镜端 → cols 8-11 / 行 -3
    S.r(M.polyDark, 13, -3, 2.0, 1);                           // 转鼓 → cols 13,14 / 行 -3
    S.r(M.polyDark, 17, -3, 4.0, 1);                           // 物镜端 → cols 17-20 / 行 -3
    S.l(M.glass.hi, 17.4, -2.6, 19.4, -2.6, true);             // 物镜镜片
    S.d(M.polyDark.edge, 13.4, -2.6, 1, true);                 // 转鼓刻度
    // —— 机匣下方：AR 系的握把（cols 8-10）在弹匣（cols 13-16）**之后**，两者都挂在行 1 那条底线上 ——
    S.r(M.poly, 0, 1, 3.0, 1);                                 // 托体 → cols 0-2 / 行 1
    S.r(M.poly, 4, 1, 2.0, 1);                                 // 托体前段 → cols 4,5 / 行 1
    S.r(M.noir, 8, 1, 9.0, 1);                                 // 机匣底 + 护圈 + 匣井 → cols 8-16 / 行 1
    // cols 24-30 行 1 在照片里是**折叠在护木下方的两脚架腿**（护木下缘实测到 +0.83、
    // 脚架体起于 +1.36，中间透着空气，被包络吞进参照）。脚架归配件系统统一上装，
    // 不入本体 —— 这里一颗格都不涂，只在行 0 留座。见 参照/配件排除.json。
    S.r(M.poly, 0, 2, 3.0, 1);                                 // 托底 → cols 0-2 / 行 2
    S.r(M.polyDark, 8, 2, 3.0, 1);                             // 握把 → cols 8-10 / 行 2
    S.r(M.polyDark, 13, 2, 4.0, 1);                            // 弹匣 → cols 13-16 / 行 2
    S.r(M.poly, 1, 3, 1.0, 1);                                 // 托底挂环 → col 1 / 行 3
    S.r(M.polyDark, 8, 3, 3.0, 1);                             // 握把 → cols 8-10 / 行 3
    S.r(M.polyDark, 13, 3, 4.0, 1);                            // 弹匣 → cols 13-16 / 行 3
    S.r(M.polyDark, 8, 4, 1.0, 1);                             // 握把底 → col 8 / 行 4
    S.r(M.polyDark, 13, 4, 3.0, 1);                            // 弹匣底板 → cols 13-15 / 行 4
    S.l(M.noir.lo, 9.4, -1.4, 29.4, -1.4, true);               // 导轨齿（检视）
    S.l(M.poly.lo, 0.4, 2.4, 2.4, 2.4, true);                  // 托底调节槽（检视）
    S.l(M.barrel.hi, 11.4, 0.6, 11.4, 0.9, true);              // 扳机（护圈洞在 cols 11,12 行 2）
    S.l(M.polyDark.edge, 11.4, 0.4, 12.4, 0.4, true);          // 弹匣释放钮（落在行 0）
    for (let i = 0; i < 2; i++) S.l(M.poly.lo, 14.4 + i, 1.4, 14.4 + i, 3.4, true);   // 匣身纵筋（检视）
    S.d(M.noir.hi, 25.4, 0.4, 1, true);                        // 两脚架座
  };
  const sr25Silhouette = 单向('sr25', sr25Body);

  // ---------- MK12 的旧版（参照图其实是 SVD）已删除 ----------
  // 第 5 批那次"照片是 SVD、按用户指定登记成 mk12"的妥协，在第 8 批补掉了：
  // 这张 SVD 轮廓归位给 svd（见本文件末尾第 8 批段），mk12 改成真实 Mk 12 SPR 的 AR 系结构。

  // ---------- QBU-09（第 9 批改按 v2 参照图重建：灰色 AR 系半自动 + 通体底盘托） ----------
  // 目标格（格心 ∪ 整格，并集 140 − 脚架腿 10 = 130）：
  //   行 -3：cols 9-11, 14,15, 18-22   行 -2：cols 9-13, 15-22   行 -1：cols 0-5, 9-28
  //   行  0：cols 0-37                 行  1：cols 0-18
  //   行  2：cols 0-2, 5, 8-11, 13-17   行 3：cols 8-10, 14-17   行 4：col 8, 14-16
  //   洞：托底开口 (3,2)、握把后缝 (2,3)、护圈 (12,2)、镜环间 (14,-2)、枪口 (37,-1)
  //   第 5 批那版是照一张**栓动 FDE 底盘**照片建的，与这张半自动 AR 系完全是两支枪 ⇒ 整份替换。
  const qbu09Body = (S) => {
    // —— 行 0 脊线：托 → 机匣 → 护木 → 裸露枪管 → 制退器 ——
    S.r(M.noir, 0, 0, 32.0, 1);                                // 托 + 机匣 + 护木 → cols 0-31 / 行 0
    S.l(M.barrel.base, 32.4, 0, 36.4, 0);                      // 裸露枪管 → cols 32-36 / 行 0
    S.r(M.barrel, 36.6, 0, 1.4, 1);                            // 制退器 → col 37 / 行 0
    // —— 行 -1：托腮垫 + 平顶导轨（cols 6-8 是托与导轨之间的台阶）——
    S.r(M.poly, 0, -1, 6.0, 1);                                // 托腮垫 → cols 0-5 / 行 -1
    S.r(M.noir, 9, -1, 20.0, 1);                               // 机匣顶 + 护木顶导轨 → cols 9-28 / 行 -1
    // —— 瞄具：镜身两行，行 -2 在 col 14 留空（两个镜环之间）——
    S.r(M.polyDark, 9, -2, 5.0, 1);                            // 镜身后段 → cols 9-13 / 行 -2
    S.r(M.polyDark, 15, -2, 8.0, 1);                           // 镜身前段 → cols 15-22 / 行 -2
    S.r(M.polyDark, 9, -3, 3.0, 1);                            // 目镜端 → cols 9-11 / 行 -3
    S.r(M.polyDark, 14, -3, 2.0, 1);                           // 转鼓 → cols 14,15 / 行 -3
    S.r(M.polyDark, 18, -3, 5.0, 1);                           // 物镜端 → cols 18-22 / 行 -3
    S.l(M.glass.hi, 18.4, -2.6, 21.4, -2.6, true);             // 物镜镜片
    S.d(M.polyDark.edge, 14.4, -2.6, 1, true);                 // 转鼓刻度
    // —— 机匣下方：托体 / 握把 / 弹匣 / 护木下导轨 ——
    S.r(M.poly, 0, 1, 19.0, 1);                                // 托 + 机匣底 + 匣井 → cols 0-18 / 行 1
    // cols 24-31 的行 1、行 2 是同一件东西：**折叠在护木下方的两脚架**
    // （护木下缘实测到 +0.97、脚架体在 +1.23~+2.4，中间透空气被包络吞了）。
    // 脚架归配件系统统一上装，不入本体 ⇒ 整块不涂。见 参照/配件排除.json。
    S.r(M.poly, 0, 2, 3.0, 1);                                 // 托底 → cols 0-2 / 行 2
    S.r(M.poly, 5, 2, 1.0, 1);                                 // 托底前块 → col 5 / 行 2
    S.r(M.polyDark, 8, 2, 4.0, 1);                             // 握把 → cols 8-11 / 行 2
    S.r(M.polyDark, 13, 2, 5.0, 1);                            // 弹匣 → cols 13-17 / 行 2
    S.r(M.polyDark, 8, 3, 3.0, 1);                             // 握把 → cols 8-10 / 行 3
    S.r(M.polyDark, 14, 3, 4.0, 1);                            // 弹匣 → cols 14-17 / 行 3
    S.r(M.polyDark, 8, 4, 1.0, 1);                             // 握把底 → col 8 / 行 4
    S.r(M.polyDark, 14, 4, 3.0, 1);                            // 弹匣底板 → cols 14-16 / 行 4
    S.l(M.noir.lo, 10.4, -1.4, 27.4, -1.4, true);              // 导轨齿（检视）
    S.l(M.poly.hi, 0.4, 1.4, 6.4, 1.4, true);                  // 托体贴腮线（检视）
    S.d(M.poly.lo, 1.4, 2.4, 1, true);                         // 托底螺栓（检视）
    S.l(M.barrel.hi, 12.6, 0.6, 12.6, 0.9, true);              // 扳机（护圈洞在 col 12，只能落在 col 13）
    for (let i = 0; i < 2; i++) S.l(M.poly.lo, 15.4 + i, 1.4, 15.4 + i, 3.4, true);   // 匣身纵筋（检视）
    S.l(M.blued.lo, 35.4, -0.4, 35.4, 0.4, true);              // 制退器槽
  };
  const qbu09Silhouette = 单向('qbu09', qbu09Body);

  // ============================================================
  // 批量第 6 批：SCAR-SSR / Vector / 汤姆逊（各一张左视图）
  // ------------------------------------------------------------
  // 同一把标尺 1 单位 = 29.4mm，len 取该 ID 型号的公开全长：
  //   scarssr  FN SCAR-H PR 20" 型、枪托收拢 1110mm ⇒ 37.8
  //   vector   KRISS Vector SMG 4.5"、枪托伸展 615mm ⇒ 20.9
  //   thompson M1928A1 18" 枪管 + 鼓弹 + 前握把 861mm ⇒ 29.3
  //
  // 标尺反查（三张图各自独立成立）：
  //   scarssr  按 20 发 7.62 弹匣外露长度 123~150mm（真实 140mm）反解出 1 单位 ≈ 31.4~33.2px，
  //            与"取 37.8 单位"自洽；照片自身量到 40 单位 = 1176mm，比公开值长 6%，
  //            差的 66mm 最可能就是枪托没完全收拢（SCAR 托每档 ≈25mm）。取公开值 37.8。
  //   vector   托底板实测 4.11 单位 = 121mm（Vector 托底 ~115mm）、裸露段 19mm；
  //   thompson 托底 119mm、前握把 125mm、散热片枪管谷径 14.4mm、全枪 861mm —— 全部对得上。
  //
  // 建模目标仍是"格心 ∪ 整格"并集，两个参照都跑到 缺=0、填洞=0。
  // ============================================================

  // ---------- SCAR-SSR：沙色底盘 + 两端折叠瞄具 ----------
  // 目标格（新图并集 170 − 排除 (20,7)(17,3) = 169；档案实画 170 格，其中 (17,3) 已登记排除）：
  //   行 -4：13, 29-30      行 -3：12-14, 29-30     行 -2：cols 0,1, 8-30
  //   行 -1：cols 0-31      行  0：cols 0-29, 31-37  行  1：cols 0-4, 7, 10-21
  //   行  2：cols 0-3, 11-15, 18-21     行  3：cols 0-2, 11-14, 17, 18-21
  //   行  4：cols 0-2, 11-14, 18-21     行  5：cols 11-14, 18-21
  //   行  6：13, 18-21      行  7：19
  //   洞：扳机护圈 (16,2)(17,2)(15,3)(16,3)
  //   cols 11-14 是握把（外露到行 6）、cols 18-21 是 20 发直匣（外露到行 7），中间隔着护圈洞。
  //   col 30 只在行 -1 有墨、行 0 是空的：照片有轻微俯仰，枪管中心在这一格正好跨过行边界。
  //   第 10 批收到第二张照片，四个口径（两图 × 格心/整格）对完只差三格，全部登记进
  //   `参照/配件排除.json` 并各附实测依据：(27,1) 与 (20,7) 是 `round(包络高度)` 的跳变伪影
  //   （两图该列下缘实测几乎同值，变的都是**上缘**），(17,3) 是压在行 3/4 分界线上、
  //   差 0.9mm 就换行的护圈前下缘薄边 —— 那一格**照画**，登记只是为了不被洞检测反咬一口。
  //   顺带把第 6批那颗查无实据的"两脚架座"(27,1) 删了。
  const scarssrBody = (S) => {
    // —— 行 0 脊线：托/机匣/护木通长，再往左是裸露枪管与消焰器 ——
    S.r(M.tan, 0, 0, 20.0, 1);                                 // 托 + 机匣上棱 → cols 0-19 / 行 0
    S.r(M.tan, 20, 0, 10.0, 1);                                // 护木上棱 → cols 20-29 / 行 0
    S.l(M.barrel.base, 30.6, 0, 36.6, 0);                      // 裸露枪管 → cols 31-36 / 行 0
    S.r(M.barrel, 36.6, 0, 1.4, 1);                            // 消焰器 → col 37 / 行 0
    // —— 行 -1：一条通长的平顶导轨（cols 0-31）——
    S.r(M.tan, 0, -1, 32.0, 1);                                // 贴腮板 + 全长上导轨 → cols 0-31 / 行 -1
    S.r(M.tan, 0, -2, 2.0, 1);                                 // 托腮垫 → cols 0,1 / 行 -2
    S.r(M.noir, 8, -2, 23.0, 1);                               // 导轨与机匣顶 → cols 8-30 / 行 -2
    S.r(M.noir, 12, -3, 3.0, 1);                               // 折叠后照门 → cols 12-14 / 行 -3
    S.r(M.noir, 13, -4, 1.0, 1);                               // → col 13 / 行 -4
    S.r(M.noir, 29, -3, 2.0, 1);                               // 折叠前准星 → cols 29,30 / 行 -3
    S.r(M.noir, 29, -4, 2.0, 1);                               // → cols 29,30 / 行 -4
    // —— 机匣下沿与握把、弹匣 ——
    S.r(M.tan, 0, 1, 5.0, 1);                                  // 托身 → cols 0-4 / 行 1
    S.r(M.tan, 7, 1, 1.0, 1);                                  // 托颈 → col 7 / 行 1
    S.r(M.noir, 10, 1, 12.0, 1);                               // 机匣底 + 护圈 + 匣井 → cols 10-21 / 行 1
    // 第 6 批这里还有一颗 `S.r(M.noir, 27, 1)` 标着"两脚架座"，已删；
    // 为什么删、以及它凭什么一度被报成"要求"，见下面弹匣底板那段的四口径对账。
    S.r(M.tan, 0, 2, 4.0, 1);                                  // 托身 → cols 0-3 / 行 2
    S.r(M.polyDark, 11, 2, 5.0, 1);                            // 握把 → cols 11-15 / 行 2
    S.r(M.polyDark, 18, 2, 4.0, 1);                            // 弹匣 → cols 18-21 / 行 2
    S.r(M.tan, 0, 3, 3.0, 1);                                  // 托身 → cols 0-2 / 行 3
    S.r(M.polyDark, 11, 3, 4.0, 1);                            // 握把 → cols 11-14 / 行 3
    S.r(M.polyDark, 17, 3, 1.0, 1);                            // 护圈前柱 → col 17 / 行 3
    S.r(M.polyDark, 18, 3, 4.0, 1);                            // 弹匣 → cols 18-21 / 行 3
    S.r(M.tan, 0, 4, 3.0, 1);                                  // 托底 → cols 0-2 / 行 4
    S.r(M.polyDark, 11, 4, 4.0, 1);                            // 握把 → cols 11-14 / 行 4
    S.r(M.polyDark, 18, 4, 4.0, 1);                            // 弹匣 → cols 18-21 / 行 4
    S.r(M.polyDark, 11, 5, 4.0, 1);                            // 握把底 → cols 11-14 / 行 5
    S.r(M.polyDark, 18, 5, 4.0, 1);                            // 弹匣 → cols 18-21 / 行 5
    S.r(M.polyDark, 13, 6, 1.0, 1);                            // 握把尾 → col 13 / 行 6
    S.r(M.polyDark, 18, 6, 4.0, 1);                            // 弹匣 → cols 18-21 / 行 6
    S.r(M.polyDark, 19, 7, 1.0, 1);                            // 弹匣底板 → col 19 / 行 7
    // 行 7 只到 col 19：新图整格口径一度把 (20,7) 也报成要求，但那是取整伪影 ——
    // 弹匣底板下缘两图实测 7.28~7.42（同一条边），是新图整格把**上缘**从 -2.03 抬到 -2.10，
    // 包络高度 9.34→9.52 才多算出一行。同理 (27,1)：护木下缘两图都停在 1.24~1.37，
    // 旧图只因 col 27 上缘高 0.04 单位让 span 落在 3.50 上（round→4）而"要求"它，
    // 相邻 cols 24/25/26/28 两图都不要求 ⇒ 一颗悬在护木中段下方的孤格不是零件。
    // 第 6 批档案里那颗标着"两脚架座"的 (27,1) 因此删掉（照片里查不到，配件也不归本轨）。
    S.l(M.barrel.hi, 15.4, 0.4, 15.4, 0.9, true);              // 扳机
    S.l(M.tan.hi, 0.4, -0.6, 4.4, -0.6, true);                 // 贴腮线（检视）
    for (let i = 0; i < 4; i++) S.l(M.noir.lo, 9.4 + i * 2.4, -1.4, 10.4 + i * 2.4, -1.4, true);      // 导轨齿（检视）
    for (let i = 0; i < 3; i++) S.l(M.poly.lo, 18.4 + i, 2.4, 18.4 + i, 4.4, true);                    // 匣身纵筋（检视）
  };
  const scarssrSilhouette = 单向('scarssr', scarssrBody);

  // ---------- Vector：一块斜切机身 + 骨架伸缩托 ----------
  // 目标格（并集 66）：
  //   行 -2：cols 8-18      行 -1：cols 0, 2-18     行  0：cols 0-3, 7-9, 12-15, 17-20
  //   行  1：cols 0, 2,3, 7-14                      行  2：cols 0-2, 7,8, 11-14
  //   行  3：1, 9
  //   洞：骨架托镂空 (1,1)、护圈 (10,0)(11,0)(9,2)(10,2)
  //   行 -1 从 col 2 一路通到 col 18：Vector 的机匣顶就是一根通长皮卡汀尼，
  //   而 col 1 行 -1 是空的 —— 伸缩托的导轨比机匣低半格，这是它最好认的一条线。
  const vectorBody = (S) => {
    S.r(M.noir, 0, -1, 1.0, 1);                                // 托尾上棱 → col 0 / 行 -1
    S.r(M.noir, 2, -1, 17.0, 1);                               // 通长顶导轨 → cols 2-18 / 行 -1
    S.r(M.noir, 8, -2, 11.0, 1);                               // 瞄具座与折叠准星 → cols 8-18 / 行 -2
    S.r(M.poly, 0, 0, 4.0, 1);                                 // 伸缩托撑杆 → cols 0-3 / 行 0
    S.r(M.poly, 7, 0, 3.0, 1);                                 // 机匣后段 → cols 7-9 / 行 0
    S.r(M.poly, 12, 0, 4.0, 1);                                // 机匣前段 → cols 12-15 / 行 0
    S.l(M.barrel.base, 17.4, 0, 20.4, 0);                      // 裸露枪管 + 消焰器 → cols 17-20 / 行 0
    S.r(M.poly, 0, 1, 1.0, 1);                                 // 托底板 → col 0 / 行 1
    S.r(M.poly, 2, 1, 2.0, 1);                                 // 撑杆 → cols 2,3 / 行 1
    S.r(M.poly, 7, 1, 8.0, 1);                                  // 机身主体 → cols 7-14 / 行 1
    S.r(M.poly, 0, 2, 3.0, 1);                                 // 托底 → cols 0-2 / 行 2
    S.r(M.poly, 7, 2, 2.0, 1);                                 // 握把 → cols 7,8 / 行 2
    S.r(M.polyDark, 11, 2, 4.0, 1);                            // 斜置弹匣井 → cols 11-14 / 行 2
    S.r(M.poly, 1, 3, 1.0, 1);                                 // 托底挂环 → col 1 / 行 3
    S.r(M.polyDark, 9, 3, 1.0, 1);                             // 弹匣底 → col 9 / 行 3
    S.d(M.barrel.hi, 9.4, -1.6, 1, true);                      // 折叠后照门
    S.d(M.barrel.hi, 17.4, -1.6, 1, true);                     // 折叠前准星
    S.l(M.noir.lo, 3.4, -0.6, 16.4, -0.6, true);               // 导轨齿（检视）
    S.d(M.poly.hi, 12.4, 1.4, 1, true);                        // 厂标（检视）
    S.d(M.poly.lo, 12.4, 2.4, 1, true);                        // 弹匣井防滑纹
  };
  const vectorSilhouette = 单向('vector', vectorBody);

  // ---------- 汤姆逊：散热片枪管 + 鼓弹 + 木握把与前握把 ----------
  // 目标格（并集 102）：
  //   行 -1：cols 8-12, 27   行  0：cols 8-26, 28,29  行  1：cols 3-22
  //   行  2：cols 0-8, 10-17, 19-22                   行  3：cols 0-5, 10-13, 15-17, 19-21
  //   行  4：cols 0-3, 10-12, 15-17, 19-20            行  5：cols 0-2, 11, 15-16
  //   无洞：col 14 行 3-5 本来就没墨（扳机护圈），量具没围住它，照样得留空。
  //   从枪托往枪口依次是：木托(0-8) / 机匣(8-17) / 木握把(10-13) / 护圈(14) / 弹鼓(15-17) / 前握把(19-22) / 散热片枪管(18-26) / 准星(27) / 补偿器(28-29)
  const thompsonBody = (S) => {
    // —— 行 0：机匣上沿 → 散热片枪管 → 补偿器 ——
    S.r(M.noir, 8, 0, 10.0, 1);                                // 机匣顶 → cols 8-17 / 行 0
    S.l(M.barrel.base, 18.4, 0, 26.4, 0);                      // 散热片枪管 → cols 18-26 / 行 0
    S.r(M.barrel, 27.6, 0, 2.0, 1);                            // Cutts 补偿器 → cols 28,29 / 行 0
    S.r(M.phosphate, 26.6, -1, 1.0, 1);                        // 前准星 → col 27 / 行 -1
    S.r(M.phosphate, 8, -1, 5.0, 1);                           // 表尺与拉机柄槽 → cols 8-12 / 行 -1
    // —— 行 1：托背 → 机匣底 → 前握把顶，一条通长 ——
    S.r(M.laminate, 3, 1, 6.0, 1);                             // 托背 → cols 3-8 / 行 1
    S.r(M.noir, 9, 1, 10.0, 1);                                // 机匣底 + 弹鼓座 → cols 9-18 / 行 1
    S.r(M.laminate, 19, 1, 4.0, 1);                            // 前握把顶 → cols 19-22 / 行 1
    // —— 木托：从托底四行楔到托颈两行 ——
    S.r(M.laminate, 0, 2, 9.0, 1);                             // 托身 → cols 0-8 / 行 2
    S.r(M.laminate, 0, 3, 6.0, 1);                             // 托身 → cols 0-5 / 行 3
    S.r(M.laminate, 0, 4, 4.0, 1);                             // 托身 → cols 0-3 / 行 4
    S.r(M.laminate, 0, 5, 3.0, 1);                             // 托底 → cols 0-2 / 行 5
    S.l(M.wood.hi, 0.4, 2.4, 5.4, 2.4, true);                  // 木纹（检视）
    // —— 木握把（col 14 是护圈洞，必须留空）——
    S.r(M.laminate, 10, 2, 4.0, 1);                            // 握把 → cols 10-13 / 行 2
    S.r(M.laminate, 10, 3, 4.0, 1);                            // 握把 → cols 10-13 / 行 3
    S.r(M.laminate, 10, 4, 3.0, 1);                            // 握把 → cols 10-12 / 行 4
    S.r(M.laminate, 11, 5, 1.0, 1);                            // 握把底 → col 11 / 行 5
    // —— 50 发弹鼓 ——
    S.r(M.noir, 14, 2, 4.0, 1);                                // 鼓顶 + 护圈上沿 → cols 14-17 / 行 2
    S.r(M.noir, 15, 3, 3.0, 1);                                // 鼓身 → cols 15-17 / 行 3
    S.r(M.noir, 15, 4, 3.0, 1);                                // 鼓身 → cols 15-17 / 行 4
    S.r(M.noir, 15, 5, 2.0, 1);                                // 鼓底 → cols 15,16 / 行 5
    S.l(M.poly.lo, 15.4, 2.4, 15.4, 4.4, true);                // 鼓身筋（检视）
    // —— 前握把 ——
    S.r(M.laminate, 19, 2, 4.0, 1);                            // 握把 → cols 19-22 / 行 2
    S.r(M.laminate, 19, 3, 3.0, 1);                            // 握把 → cols 19-21 / 行 3
    S.r(M.laminate, 19, 4, 2.0, 1);                            // 握把 → cols 19,20 / 行 4
    for (let i = 0; i < 3; i++) S.d(M.wood.lo, 20.4 + i, 2.4, 1, true);        // 指槽（检视）
    for (let i = 0; i < 3; i++) S.d(M.barrel.hi, 20.4 + i * 2, 0.4, 1, true);  // 散热片高光（检视）
    S.d(M.barrel.hi, 9.4, -1.4, 1, true);                      // 拉机柄
    S.l(M.blued.lo, 28.4, -0.4, 28.4, 0.4, true);              // 补偿器槽
  };
  const thompsonSilhouette = 单向('thompson', thompsonBody);

  // ============================================================
  // 批量第 7 批：G36 / FAMAS / HK416（各一张左视图）
  // ------------------------------------------------------------
  // 同一把标尺 1 单位 = 29.4mm，len 取该 ID 型号的公开全长：
  //   g36    999mm（枪托伸展）        ⇒ 34.0
  //   famas  1097mm（F1 标准托）      ⇒ 37.3
  //   hk416  925mm（14.5" 型、枪托伸展）⇒ 31.5
  //
  // 标尺反查（三张图各自独立成立）：
  //   g36    裸露枪管 cols 29-32 实测 16~17mm（G36 枪口直径级）；全枪 999mm 与公开值同。
  //   famas  大环提把顶面实测在膛轴上方 3.74~4.05 单位 = 110~119mm，
  //          与 FAMAS 提把顶到膛线的实际高差 110mm 对上；全枪 1097mm 与公开值同。
  //   hk416  枪口枪管 cols 27-29 实测 17~18mm、等厚窗 19.8mm（HK416 14.5" 枪管口径级）。
  //
  // 建模目标 = 格心 ∪ 整格；两个参照都跑到 缺=0、填洞=0。
  // 三把的机匣/聚合物件一律用第 6 批新加的 M.noir（照片实测全是中性黑，不带蓝相）。
  // ============================================================

  // ---------- G36：骨架折叠托 + 提把式瞄准镜 ----------
  // 目标格（并集 147）：
  //   行 -4：cols 10-21（提把顶横梁）  行 -3：cols 10-13, 21-22（提把两支耳，中间 14-20 是空的）
  //   行 -2：cols 8-20, 22-27（col 21 是洞）  行 -1：cols 0-28（通长）
  //   行  0：cols 0-1, 8-33（cols 2-7 是洞）  行  1：cols 0-4, 9-18, 21, 28
  //   行  2：cols 0-2, 9-11, 14-18（cols 12-13 是洞）  行  3/4：cols 0-1, 9-11, 15-18
  //   行  5：col 11, cols 15-18            行  6：cols 15-16
  //   两处大洞都是本体特征：cols 2-7 行 0 = 骨架折叠托中间的镂空；
  //   行 -3 cols 14-20 = 提把横梁底下的空档。这两处绝不能填成实心。
  const g36Body = (S) => {
    // —— 行 0 脊线：托尾 → 机匣/护木 → 裸露枪管 + 消焰器 ——
    S.r(M.noir, 0, 0, 2.0, 1);                                 // 托尾块 → cols 0,1 / 行 0
    S.r(M.noir, 8, 0, 21.0, 1);                                // 机匣 + 护木 → cols 8-28 / 行 0
    S.l(M.barrel.base, 29.4, 0, 33.4, 0);                      // 裸露枪管 → cols 29-33 / 行 0
    // —— 行 -1：一条通长上沿（托撑杆 + 机匣顶 + 护木顶导轨）——
    S.r(M.noir, 0, -1, 29.0, 1);                               // → cols 0-28 / 行 -1
    // —— 提把式瞄准镜：横梁在行 -4，两支耳在行 -3，中间 cols 14-20 必须留空 ——
    S.r(M.polyDark, 8, -2, 13.0, 1);                           // 镜身前段 → cols 8-20 / 行 -2
    S.r(M.polyDark, 22, -2, 6.0, 1);                           // 镜身后段 → cols 22-27 / 行 -2
    S.r(M.polyDark, 10, -3, 4.0, 1);                           // 后支耳 → cols 10-13 / 行 -3
    S.r(M.polyDark, 21, -3, 2.0, 1);                           // 前支耳 → cols 21,22 / 行 -3
    S.r(M.polyDark, 10, -4, 12.0, 1);                          // 提把横梁 → cols 10-21 / 行 -4
    S.l(M.glass.hi, 22.4, -1.6, 26.4, -1.6, true);             // 物镜（落在行 -2 的镜身后段上）
    S.d(M.polyDark.edge, 12.4, -2.6, 1, true);                 // 调焦环（检视）
    // —— 骨架折叠托：cols 2-7 行 0 是镂空，只画上撑杆（行 -1 那条）与下缘 ——
    S.r(M.noir, 0, 1, 5.0, 1);                                 // 托下缘 → cols 0-4 / 行 1
    S.r(M.noir, 0, 2, 3.0, 1);                                 // 托后块 → cols 0-2 / 行 2
    S.r(M.noir, 0, 3, 2.0, 1);                                 // 托后块 → cols 0,1 / 行 3
    S.r(M.noir, 0, 4, 2.0, 1);                                 // 托后块 → cols 0,1 / 行 4
    S.d(M.noir.edge, 1.4, 3.4, 1, true);                       // 折叠轴销（检视）
    // —— 握把、护圈、半透明弹匣 ——
    S.r(M.noir, 9, 1, 10.0, 1);                                // 机匣底 + 护圈 + 匣顶 → cols 9-18 / 行 1
    S.r(M.noir, 21, 1, 1.0, 1);                                // 背带环座 → col 21 / 行 1
    S.r(M.phosphate, 28, 1, 1.0, 1);                           // 折叠前准星座 → col 28 / 行 1
    S.r(M.noir, 9, 2, 3.0, 1);                                 // 握把 → cols 9-11 / 行 2
    S.r(M.alu, 14, 2, 5.0, 1);                                 // 半透明弹匣 → cols 14-18 / 行 2
    S.r(M.noir, 9, 3, 3.0, 1);                                 // 握把 → cols 9-11 / 行 3
    S.r(M.alu, 15, 3, 4.0, 1);                                 // 弹匣 → cols 15-18 / 行 3
    S.r(M.noir, 9, 4, 3.0, 1);                                 // 握把 → cols 9-11 / 行 4
    S.r(M.alu, 15, 4, 4.0, 1);                                 // 弹匣 → cols 15-18 / 行 4
    S.r(M.noir, 11, 5, 1.0, 1);                                // 握把底 → col 11 / 行 5
    S.r(M.alu, 15, 5, 4.0, 1);                                 // 弹匣 → cols 15-18 / 行 5
    S.r(M.polyDark, 15, 6, 2.0, 1);                            // 弹匣底板 → cols 15,16 / 行 6
    S.l(M.barrel.hi, 12.4, 0.6, 12.4, 1.4, true);              // 扳机（col 12 行 1，护圈洞在行 2 的 cols 12-13）
    for (let i = 0; i < 3; i++) S.l(M.alu.lo, 15.4 + i, 2.4, 15.4 + i, 4.4, true);   // 匣内可视弹量（检视）
  };
  const g36Silhouette = 单向('g36', g36Body);

  // ---------- FAMAS：无托 + 那个标志性的大环提把 ----------
  // 目标格（并集 190）：
  //   行 -4：cols 13-30（提把顶横梁，18 格长）  行 -3：cols 13,14, 29,30（两支耳）
  //   行 -2：cols 0-4, 13,14, 21, 29,30         行 -1：cols 0-31（通长）
  //   行  0：cols 0-37（通长到枪口）            行  1：cols 0-25, 29,30
  //   行  2：cols 0-12, 14-18, 21               行  3：cols 0-5, 8-12, 14-16, 20
  //   行  4：cols 8-12, 14-16   行  5/6：cols 8-11, 14-16   行  7：cols 8-11
  //   洞：提把底下 cols 15-28（行 -2、-3 两大片）、护圈 (17,3)(18,3)(19,3)(19,2)(20,2)
  //   无托布局：弹匣 cols 8-11 在握把 cols 14-16 的**后面**（贴近托尾），这是 FAMAS 的身份。
  const famasBody = (S) => {
    // —— 行 0：从托尾一路通到枪口（无托机匣就是枪身，没有独立的托）——
    S.r(M.noir, 0, 0, 31.0, 1);                                // 机匣 + 护木 → cols 0-30 / 行 0
    S.l(M.barrel.base, 31.4, 0, 36.4, 0);                      // 裸露枪管 → cols 31-36 / 行 0
    S.r(M.barrel, 36.6, 0, 1.4, 1);                            // 消焰器 → col 37 / 行 0
    S.r(M.noir, 0, -1, 32.0, 1);                               // 机匣顶 / 护木背上棱 → cols 0-31 / 行 -1
    // —— 大环提把：横梁在行 -4，前后两支耳在行 -3，中间整段是空的 ——
    S.r(M.polyDark, 13, -4, 18.0, 1);                          // 提把横梁 → cols 13-30 / 行 -4
    S.r(M.polyDark, 13, -3, 2.0, 1);                           // 后支耳 → cols 13,14 / 行 -3
    S.r(M.polyDark, 29, -3, 2.0, 1);                           // 前支耳 → cols 29,30 / 行 -3
    S.r(M.noir, 0, -2, 5.0, 1);                                // 托尾上鼓 → cols 0-4 / 行 -2
    S.r(M.polyDark, 13, -2, 2.0, 1);                           // 后支耳座 → cols 13,14 / 行 -2
    S.r(M.polyDark, 21, -2, 1.0, 1);                           // 横梁中段立柱 → col 21 / 行 -2
    S.r(M.polyDark, 29, -2, 2.0, 1);                           // 前支耳座 → cols 29,30 / 行 -2
    S.l(M.glass.hi, 14.4, -3.6, 20.4, -3.6, true);             // 提把内瞄具镜片（检视，落在行 -4 横梁上）
    S.l(M.noir.lo, 2.4, -0.9, 28.4, -0.9, true);               // 机匣顶导轨齿（检视；行 -2 大片是提把下的洞，不能画在那）
    // —— 机匣与护木侧面 ——
    S.r(M.noir, 0, 1, 26.0, 1);                                // 机匣下沿 → cols 0-25 / 行 1
    S.r(M.noir, 29, 1, 2.0, 1);                                // 护木前段下沿 → cols 29,30 / 行 1
    S.r(M.noir, 0, 2, 13.0, 1);                                // 机匣底后段 → cols 0-12 / 行 2
    S.r(M.noir, 14, 2, 5.0, 1);                                // 护圈上沿 → cols 14-18 / 行 2
    S.r(M.polyDark, 21, 2, 1.0, 1);                            // 弹匣卡笋 → col 21 / 行 2
    S.r(M.noir, 0, 3, 6.0, 1);                                 // 托底 → cols 0-5 / 行 3
    S.r(M.noir, 8, 3, 5.0, 1);                                 // 匣井 → cols 8-12 / 行 3
    S.r(M.polyDark, 14, 3, 3.0, 1);                            // 握把 → cols 14-16 / 行 3
    S.r(M.polyDark, 20, 3, 1.0, 1);                            // 护圈前柱 → col 20 / 行 3
    for (let i = 0; i < 4; i++) S.l(M.noir.lo, 2.4 + i * 2.0, 0.4, 3.4 + i * 2.0, 0.4, true);   // 托底防滑纹（检视）
    // —— 无托：弹匣在握把**后面**，一路垂到行 7 ——
    S.r(M.polyDark, 8, 4, 5.0, 1);                             // 弹匣 → cols 8-12 / 行 4
    S.r(M.polyDark, 14, 4, 3.0, 1);                            // 握把 → cols 14-16 / 行 4
    S.r(M.polyDark, 8, 5, 4.0, 1);                             // 弹匣 → cols 8-11 / 行 5
    S.r(M.polyDark, 14, 5, 3.0, 1);                            // 握把 → cols 14-16 / 行 5
    S.r(M.polyDark, 8, 6, 4.0, 1);                             // 弹匣 → cols 8-11 / 行 6
    S.r(M.polyDark, 14, 6, 3.0, 1);                            // 握把底 → cols 14-16 / 行 6
    S.r(M.polyDark, 8, 7, 4.0, 1);                             // 弹匣底板 → cols 8-11 / 行 7
    S.l(M.barrel.hi, 17.4, 0.6, 17.4, 1.4, true);              // 扳机（col 17 行 1，护圈洞在行 2-3）
  };
  const famasSilhouette = 单向('famas', famasBody);

  // ---------- HK416：四面护木 + 平顶导轨 + 伸缩托 ----------
  // 目标格（并集 140）：
  //   行 -3：cols 10-12, 24,25（前后瞄具）      行 -2：cols 10-12, 24,25
  //   行 -1：cols 0-27（通长平顶导轨）          行  0：cols 0-6, 8-31
  //   行  1：cols 0-5, 8-24, 26                 行  2：cols 0-3, 8-17   行  3：cols 0-2, 8-17
  //   行  4：cols 8-11, 14-17   行  5：cols 9,10, 14-17   行  6：cols 14-17   行  7：cols 15,16
  //   无洞：col 7 行 0 与 col 6/7 行 1 只是本来就没墨（托与机匣之间的缓冲管空档），不是镂空。
  const hk416Body = (S) => {
    // —— 行 0：托 → 机匣/护木 → 裸露枪管 → 消焰器（col 7 是缓冲管空档，留白）——
    S.r(M.polyDark, 0, 0, 7.0, 1);                             // 伸缩托 → cols 0-6 / 行 0
    S.r(M.noir, 8, 0, 19.0, 1);                                // 机匣 + 四面导轨护木 → cols 8-26 / 行 0
    S.l(M.barrel.base, 27.4, 0, 30.4, 0);                      // 裸露枪管 → cols 27-30 / 行 0
    S.r(M.barrel, 30.6, 0, 1.0, 1);                            // QD 消焰器 → col 31 / 行 0
    S.r(M.noir, 0, -1, 28.0, 1);                               // 全长平顶导轨 → cols 0-27 / 行 -1
    S.r(M.noir, 10, -2, 3.0, 1);                               // 全息瞄具 → cols 10-12 / 行 -2
    S.r(M.noir, 10, -3, 3.0, 1);                               // → cols 10-12 / 行 -3
    S.r(M.phosphate, 24, -2, 2.0, 1);                          // 折叠前准星 → cols 24,25 / 行 -2
    S.r(M.phosphate, 24, -3, 2.0, 1);                          // → cols 24,25 / 行 -3
    S.l(M.glass.hi, 10.4, -2.6, 11.4, -2.6, true);             // 瞄具视窗
    for (let i = 0; i < 6; i++) S.l(M.noir.lo, 13.4 + i * 2.0, -0.9, 14.4 + i * 2.0, -0.9, true);  // 导轨齿（检视，画在行 -1 的通长导轨上）
    // —— 机匣下沿、握把、弹匣 ——
    S.r(M.polyDark, 0, 1, 6.0, 1);                             // 托底 → cols 0-5 / 行 1
    S.r(M.noir, 8, 1, 17.0, 1);                                // 机匣底 + 护木底 → cols 8-24 / 行 1
    S.r(M.noir, 26, 1, 1.0, 1);                                // 背带环 → col 26 / 行 1
    S.r(M.polyDark, 0, 2, 4.0, 1);                             // 托底 → cols 0-3 / 行 2
    S.r(M.noir, 8, 2, 10.0, 1);                                // 护圈 + 匣井 → cols 8-17 / 行 2
    S.r(M.polyDark, 0, 3, 3.0, 1);                             // 托底 → cols 0-2 / 行 3
    S.r(M.polyDark, 8, 3, 10.0, 1);                            // 握把 + 弹匣 → cols 8-17 / 行 3
    S.r(M.polyDark, 8, 4, 4.0, 1);                             // 握把 → cols 8-11 / 行 4
    S.r(M.polyDark, 14, 4, 4.0, 1);                            // 弹匣 → cols 14-17 / 行 4
    S.r(M.polyDark, 9, 5, 2.0, 1);                             // 握把底 → cols 9,10 / 行 5
    S.r(M.polyDark, 14, 5, 4.0, 1);                            // 弹匣 → cols 14-17 / 行 5
    S.r(M.polyDark, 14, 6, 4.0, 1);                            // 弹匣 → cols 14-17 / 行 6
    S.r(M.polyDark, 15, 7, 2.0, 1);                            // 弹匣底板 → cols 15,16 / 行 7
    S.l(M.barrel.hi, 12.4, 0.6, 12.4, 1.4, true);              // 扳机
    for (let i = 0; i < 2; i++) S.l(M.poly.lo, 15.4 + i, 3.4, 15.4 + i, 5.4, true);   // 匣身纵筋（检视）
    S.d(M.polyDark.edge, 2.4, 0.4, 1, true);                   // 伸缩档位钮（检视）
  };
  const hk416Silhouette = 单向('hk416', hk416Body);

  // ============================================================
  // 批量第 8 批：SVD / MK12（重做）/ VSK-94 / M14 EBR
  // ------------------------------------------------------------
  // 这批的来由要先说清：用户发来的三张"VSK-94 / SVD / M14EBR"参照图，
  // 逐格比对下来**就是第 5 批 sr25 / mk12 / qbu09 用的那三张照片本身**
  // （sr25 那张按消音器定标尺后 upx 27.98 vs 28.58，覆盖 99%；另两张的"多"格清单与当时一字不差）。
  // 照标注直接建会得到 vsk94≡sr25、svd≡mk12、m14ebr≡qbu09 三对同骨轮廓 —— 正是合同禁的
  // "同一套轮廓换个 ID 冒充"。用户答复"你随机改，大体不差做点差异化由你"，于是本批的口径是：
  //   · svd    ← 那张图本来就是 SVD，**归位给 svd**，按照片逐格建（可验证，见下）
  //   · mk12   ← 反过来改成真实 Mk 12 SPR 的结构（AR-10 系平顶机匣 + 伸缩托 + 缓冲管），
  //              顺带把第 5 批那次"照片是 SVD 却登记成 mk12"的妥协补掉
  //   · vsk94  ← 按 VSK-94 真实性型号结构建（9×90mm 整体消声短卡宾、折叠骨架托、侧轨瞄具）
  //   · m14ebr ← 按 M14 EBR 真实性型号结构建（Sage 底盘 + 后竖握把 + 短护木 + 导气杆）
  //
  // 验收口径分两种，别混：
  //   svd 有参照照片 ⇒ 跑 _gun_grid.js，目标 = 格心 ∪ 整格，要求 缺=0、填洞=0。
  //   mk12/vsk94/m14ebr 没有对应照片 ⇒ 栅格对表无从谈起，改用**尺寸自审**：
  //     每个零件按公开毫米数换算成格子写死，注释里标 mm，由 工具/_gun_spec.js 把
  //     实绘的每一格反算回毫米列成表核对。这三把的轮廓置信度**低于**照片驱动的那批，
  //     等真正的参照图到位要回头复核。
  //
  // 全长仍走统一标尺 1 单位 = 29.4mm：
  //   svd 1225mm ⇒ 41.7，超出规范上限 40，按第 5 批对 mk12 用过的同一口径压到 40.0（-4%）
  //   mk12 1054mm ⇒ 35.9、vsk94 878mm ⇒ 29.9、m14ebr 940mm ⇒ 32.0
  // ============================================================

  // ---------- SVD（参照照片，全长压到 40.0） ----------
  // 目标格（格心 ∪ 整格，共 122）：
  //   行 -3：cols 7-10, 12-19     行 -2：cols 7-12, 15-19（cols 13,14 是镜环之间的空档）
  //   行 -1：cols 7-30, 37,38     行  0：cols 0-17, 19-27, 30-39
  //   行  1：cols 0-4, 9,10, 12, 14-17          行  2：cols 0-4, 8,9, 11, 14-17
  //   行  3：cols 0-9, 15,16
  //   洞：骨架托减重槽 cols 5-8 行 1-2、护圈 (10,2)(11,1)、镜下 (13,-2)(14,-2)
  const svdBody = (S) => {
    // —— 行 0 脊线：木托上棱 → 机匣 → 护木尾 → 裸露枪管 + 消焰器 ——
    S.r(M.laminate, 0, 0, 10.0, 1);                            // 托背上棱 → cols 0-9 / 行 0
    S.r(M.blued, 10, 0, 8.0, 1);                               // 机匣 → cols 10-17 / 行 0
    S.r(M.laminate, 19, 0, 9.0, 1);                            // 层压木护木 → cols 19-27 / 行 0
    S.l(M.barrel.base, 30.4, 0, 37.4, 0);                      // 裸露枪管 → cols 30-37 / 行 0
    S.r(M.barrel, 37.6, 0, 2.4, 1);                            // 消焰器 → cols 38,39 / 行 0
    // —— 护木与导气管整条叠在膛轴上方（AK 系结构），cols 28-30 是导气箍 ——
    S.r(M.polyDark, 7, -1, 12.0, 1);                           // 镜身下沿 → cols 7-18 / 行 -1
    S.r(M.laminate, 19, -1, 9.0, 1);                           // 护木 + 导气管上棱 → cols 19-27 / 行 -1
    S.r(M.phosphate, 28, -1, 3.0, 1);                          // 导气箍 → cols 28-30 / 行 -1
    S.r(M.phosphate, 36.6, -1, 2.4, 1);                        // 前准星座 → cols 37,38 / 行 -1
    // —— PSO 瞄具：镜身两行 + 转鼓一行，行 -2 在 cols 13,14 要留空 ——
    S.r(M.polyDark, 7, -2, 6.0, 1);                            // 镜身后段 → cols 7-12 / 行 -2
    S.r(M.polyDark, 15, -2, 5.0, 1);                           // 镜身前段 → cols 15-19 / 行 -2
    S.r(M.polyDark, 7, -3, 4.0, 1);                            // 目镜端 → cols 7-10 / 行 -3
    S.r(M.polyDark, 12, -3, 8.0, 1);                           // 镜身顶 + 转鼓 → cols 12-19 / 行 -3
    S.l(M.glass.hi, 15.4, -2.6, 18.4, -2.6, true);             // 物镜
    S.d(M.polyDark.edge, 12.4, -2.6, 1, true);                 // 转鼓刻度
    // —— 骨架托：cols 5-8 行 1-2 是减重槽，必须留空 ——
    S.r(M.laminate, 0, 1, 5.0, 1);                             // 托身 → cols 0-4 / 行 1
    S.r(M.laminate, 0, 2, 5.0, 1);                             // 托身 → cols 0-4 / 行 2
    S.r(M.laminate, 0, 3, 10.0, 1);                            // 托底下棱 → cols 0-9 / 行 3
    S.r(M.laminate, 8, 2, 2.0, 1);                             // 托颈 → cols 8,9 / 行 2
    S.r(M.laminate, 9, 1, 2.0, 1);                             // 握把颈 → cols 9,10 / 行 1
    S.r(M.laminate, 12, 1, 1.0, 1);                            // 护圈后柱 → col 12 / 行 1
    S.r(M.laminate, 11, 2, 1.0, 1);                            // 护圈前柱 → col 11 / 行 2
    S.l(M.wood.hi, 0.4, 2.4, 4.4, 2.4, true);                  // 托身木纹（检视）
    S.d(M.laminate.edge, 1.4, 3.4, 1, true);                   // 背带环座
    // —— 10 发短匣 ——
    S.r(M.polyDark, 14, 1, 4.0, 1);                            // 匣顶 → cols 14-17 / 行 1
    S.r(M.polyDark, 14, 2, 4.0, 1);                            // 匣身 → cols 14-17 / 行 2
    S.r(M.polyDark, 15, 3, 2.0, 1);                            // 匣底 → cols 15,16 / 行 3
    for (let i = 0; i < 2; i++) S.l(M.poly.lo, 15.4 + i, 1.4, 15.4 + i, 2.4, true);   // 匣身纵筋（检视）
    S.l(M.barrel.hi, 12.4, 0.6, 12.4, 1.4, true);              // 扳机
    S.l(M.barrel.hi, 14.4, 0.4, 15.4, 1.4, true);              // 拉机柄（球头）
    for (let i = 0; i < 4; i++) S.l(M.laminate.lo, 20.4 + i * 2.0, -1.4, 21.4 + i * 2.0, -1.4, true);  // 护木开槽（检视）
    S.l(M.blued.lo, 37.4, -0.4, 37.4, 0.4, true);              // 消焰器槽
  };
  const svdSilhouette = 单向('svd', svdBody);

  // ---------- MK12：按第二张参照图重建（107 格）----------
  // 目标格（格心 ∪ 整格，并集 113 − 脚架腿 6 = 107）：
  //   行  4：col 9                     行  3：cols 0-1, 8-9, 12-15
  //   行  2：cols 0-4, 8-9, 11, 13-15   行  1：cols 0-6, 8-15
  //   行  0：cols 0-35（通长脊线）      行 -1：cols 8-29   行 -2：cols 8-20   行 -3：col 13
  //   洞：(10,2)、(12,2) —— 护圈两侧各留一格空，不能画成实心。
  // 与第 8 批那版的实质差别：**托是 A2 式固定三角托**（行 1→3 在 cols 0-6 逐级收窄，
  // 不是可伸缩托那种"行 1 一整条 + 行 2 一格托底板"），导轨与镜身从 col 8 起而不是 col 13 起。
  const mk12Body = (S) => {
    // —— 行 0 脊线：托 → 机匣 → 护木 → 枪管 → 消焰器 ——
    S.r(M.noir, 0, 0, 30.0, 1);                                // 托 + 机匣 + 护木 → cols 0-29 / 行 0
    S.l(M.barrel.base, 30.4, 0, 34.4, 0);                      // 裸露枪管 → cols 30-34 / 行 0
    S.r(M.barrel, 34.6, 0, 1.4, 1);                            // 消焰器 → col 35 / 行 0
    // —— 平顶导轨 + 光学镜 ——
    S.r(M.noir, 8, -1, 22.0, 1);                               // 机匣顶 + 护木顶导轨 → cols 8-29 / 行 -1
    S.r(M.polyDark, 8, -2, 13.0, 1);                           // 镜身 → cols 8-20 / 行 -2
    S.r(M.polyDark, 13, -3, 1.0, 1);                           // 转鼓顶 → col 13 / 行 -3
    S.l(M.glass.hi, 17.4, -1.6, 19.4, -1.6, true);             // 物镜（检视）
    S.l(M.noir.lo, 9.4, -1.4, 28.4, -1.4, true);               // 导轨齿（检视）
    // —— A2 固定三角托：cols 0-6 从行 1 收到行 3 ——
    S.r(M.poly, 0, 1, 7.0, 1);                                 // 托上缘 → cols 0-6 / 行 1
    S.r(M.poly, 0, 2, 5.0, 1);                                 // 托中段 → cols 0-4 / 行 2
    S.r(M.poly, 0, 3, 2.0, 1);                                 // 托底角 → cols 0-1 / 行 3
    S.l(M.poly.hi, 0.4, 1.4, 6.4, 1.4, true);                  // 贴腮线（检视）
    // —— 机匣下沿：cols 16-22 与 cols 26 在照片里是空的（握把/弹匣凹槽、护木下缘）——
    S.r(M.noir, 8, 1, 8.0, 1);                                 // 机匣底 → cols 8-15 / 行 1
    // cols 23-29 行 1 是照片里那具**折叠两脚架**（护木下缘到 +0.83、脚架体起于 +1.14，
    // 中间透空气；col 26 与 col 30 行 1 在照片里干脆没墨 —— 真导轨不会这么断）。
    // 脚架归配件系统，不入本体 ⇒ 这里整条不涂。见 参照/配件排除.json。
    // —— 握把 + 护圈 + 弹匣（护圈洞在 (10,2)(12,2)）——
    S.r(M.polyDark, 8, 2, 2.0, 1);                             // 握把背 → cols 8,9 / 行 2
    S.r(M.polyDark, 11, 2, 1.0, 1);                             // 护圈顶横杆 → col 11 / 行 2
    S.r(M.polyDark, 13, 2, 3.0, 1);                             // 匣顶 → cols 13-15 / 行 2
    S.r(M.polyDark, 8, 3, 2.0, 1);                             // 握把 → cols 8,9 / 行 3
    S.r(M.polyDark, 12, 3, 4.0, 1);                             // 弹匣上段 → cols 12-15 / 行 3
    S.r(M.polyDark, 9, 4, 1.0, 1);                             // 握把底 → col 9 / 行 4
    S.l(M.barrel.hi, 10.6, 0.6, 10.6, 0.9, true);              // 扳机（护圈洞里只有 col 11 有格，落在这）
    S.l(M.poly.lo, 13.4, 2.4, 13.4, 3.4, true);                // 匣身纵筋（检视）
    S.d(M.noir.hi, 24.4, -0.6, 1, true);                        // 复进助推器（检视）
    S.l(M.blued.lo, 34.4, -0.4, 34.4, 0.4, true);              // 消焰器槽
  };
  const mk12Silhouette = 单向('mk12', mk12Body);

  // ---------- VSK-94：9×90mm 整体消声短卡宾 ----------
  // 总长 878mm 取公开值（高置信）；实绘 882mm 与声明一致。
  // **内部分配没有照片可验**，逐件实际毫米数由 工具/_gun_spec.js vsk94 现算，注释不背书。
  // 与 svd 的区别：托是**细骨架**（cols 0-7 只有两行撑杆，不是 SVD 那种四行实木托），
  // 前面是一根**粗短的消声筒**而不是木护木，整枪短 10 格。
  const vsk94Body = (S) => {
    S.r(M.noir, 0, 0, 30.0, 1);                                // 通长脊线 → cols 0-29 / 行 0
    S.r(M.polyDark, 0, 1, 8.0, 1);                             // 折叠骨架托撑杆 → cols 0-7 / 行 1
    S.r(M.polyDark, 0, 0, 1.0, 3);                             // 托底板 → col 0 / 行 0-2
    S.r(M.noir, 7, 1, 8.0, 1);                                 // 机匣下沿 → cols 7-14 / 行 1
    S.r(M.polyDark, 16, -1, 11.0, 3);                          // 整体消声筒 → cols 16-26 / 行 -1..1
    S.l(M.barrel.base, 27.4, 0, 29.4, 0);                      // 裸露枪管 → cols 27-29 / 行 0
    S.r(M.phosphate, 26.6, -2, 1.4, 1);                        // 前准星座 → cols 27 / 行 -2
    S.r(M.noir, 7, -1, 10.0, 1);                               // 机匣顶 + 侧轨 → cols 7-16 / 行 -1
    S.r(M.polyDark, 10, -3, 7.0, 1);                           // 瞄具顶 → cols 10-16 / 行 -3
    S.r(M.polyDark, 10, -2, 7.0, 1);                           // 瞄具身 → cols 10-16 / 行 -2
    S.r(M.polyDark, 11, 2, 3.0, 1);                            // 握把 → cols 11-13 / 行 2
    S.r(M.polyDark, 14, 2, 3.0, 1);                            // 弹匣顶 → cols 14-16 / 行 2
    S.r(M.polyDark, 11, 3, 3.0, 1);                            // 握把 → cols 11-13 / 行 3
    S.r(M.polyDark, 15, 3, 2.0, 1);                            // 弹匣 → cols 15,16 / 行 3
    S.r(M.polyDark, 12, 4, 2.0, 1);                            // 握把底 → cols 12,13 / 行 4
    S.r(M.polyDark, 15, 4, 1.0, 1);                            // 弹匣底 → col 15 / 行 4
    S.l(M.glass.hi, 13.4, -2.6, 15.4, -2.6, true);             // 物镜
    S.l(M.poly.lo, 16.4, -0.4, 26.4, -0.4, true);              // 消声筒环筋（检视）
    S.l(M.polyDark.lo, 1.4, 1.4, 6.4, 1.4, true);              // 托撑杆减重槽（检视）
    S.l(M.barrel.hi, 13.4, 0.6, 13.4, 1.4, true);              // 扳机
    S.d(M.barrel.hi, 9.4, -0.6, 1, true);                      // 保险/拉机柄
  };
  const vsk94Silhouette = 单向('vsk94', vsk94Body);

  // ---------- M14 EBR：Sage 底盘 + 后竖握把 + 短护木 ----------
  // 总长 940mm 取公开值（高置信）；实绘 941mm 与声明一致。
  // **内部分配没有照片可验**，逐件实际毫米数由 工具/_gun_spec.js m14ebr 现算，注释不背书。
  // 与 mk12（同为 7.62 半自动、都有平顶导轨）的区别必须落在结构上而不是颜色上：
  // EBR 的**机匣右侧那根导气杆**（cols 20-25 行 -2 单独一条）、**底盘托下方的后竖握把**
  // （cols 4-6 行 2-4），以及**明显更短的护木** —— 这三条都是 EBR 的真特征。
  const m14ebrBody = (S) => {
    S.r(M.drab, 0, 0, 32.0, 1);                                // 通长脊线 → cols 0-31 / 行 0
    S.r(M.drab, 0, 1, 9.0, 1);                                 // 底盘托体 → cols 0-8 / 行 1
    S.r(M.polyDark, 0, 2, 2.0, 1);                             // 托底 → cols 0,1 / 行 2
    S.r(M.drab, 2, 2, 2.0, 1);                                 // 托腔后壁 → cols 2,3 / 行 2
    S.r(M.drab, 7, 2, 2.0, 1);                                 // 托腔前壁 → cols 7,8 / 行 2
    S.r(M.polyDark, 4, 2, 3.0, 3);                             // 后竖握把 → cols 4-6 / 行 2-4
    S.r(M.noir, 9, 1, 10.0, 1);                                // 机匣下沿 → cols 9-18 / 行 1
    S.r(M.noir, 19, 1, 8.0, 1);                                // 护木下沿 → cols 19-26 / 行 1
    S.r(M.noir, 8, -1, 11.0, 1);                               // 机匣顶 + 平顶导轨 → cols 8-18 / 行 -1
    S.r(M.noir, 19, -1, 8.0, 1);                               // 护木顶导轨 → cols 19-26 / 行 -1
    S.r(M.phosphate, 20, -2, 6.0, 1);                          // 导气杆（EBR 的招牌）→ cols 20-25 / 行 -2
    S.r(M.polyDark, 12, -2, 9.0, 1);                           // 光学瞄具 → cols 12-20 / 行 -2
    S.l(M.barrel.base, 27.4, 0, 30.4, 0);                      // 裸露枪管 → cols 27-30 / 行 0
    S.r(M.barrel, 30.6, 0, 1.4, 1);                            // 消焰器 → col 31,32 / 行 0
    S.r(M.polyDark, 13, 2, 3.0, 1);                            // 主握把 + 护圈 → cols 13-15 / 行 2
    S.r(M.polyDark, 16, 2, 4.0, 1);                            // 弹匣顶 → cols 16-19 / 行 2
    S.r(M.polyDark, 13, 3, 3.0, 1);                            // 主握把 → cols 13-15 / 行 3
    S.r(M.polyDark, 16, 3, 4.0, 1);                            // 弹匣 → cols 16-19 / 行 3
    S.r(M.polyDark, 13, 4, 2.0, 1);                            // 主握把底 → cols 13,14 / 行 4
    S.r(M.polyDark, 16, 4, 4.0, 1);                            // 弹匣 → cols 16-19 / 行 4
    S.r(M.polyDark, 17, 5, 2.0, 1);                            // 弹匣 → cols 17,18 / 行 5
    S.l(M.glass.hi, 17.4, -1.6, 19.4, -1.6, true);             // 物镜
    S.l(M.drab.hi, 0.4, 1.4, 7.4, 1.4, true);                  // 托体贴腮线（检视）
    S.l(M.noir.lo, 19.4, -0.4, 26.4, -0.4, true);              // 护木导轨齿（检视）
    S.l(M.barrel.hi, 15.4, 0.6, 15.4, 1.4, true);              // 扳机
    S.d(M.barrel.hi, 10.4, -0.6, 1, true);                     // 拉机柄
  };
  const m14ebrSilhouette = 单向('m14ebr', m14ebrBody);

  // ============================================================
  // 批量第 11 批：CF05 / EVO-III / P90
  // ------------------------------------------------------------
  // 同一把标尺 1 单位 = 29.4mm，len 取该 ID 型号的公开全长：
  //   cf05  21.4 单位 = 630mm —— 05 式枪托展开的常引值，**中置信**（本机取不到权威页面）
  //   evo3  19.4 单位 = 570mm —— Scorpion EVO 3 A1 枪托展开，中置信
  //   p90   18.0 单位 —— **不是 500mm÷29.4（那是 17.0）**：真实长度低于规范下限 18，
  //          用户选定"把 p90 拉长到 18"，于是这一把的标尺变成 27.8mm/单位、比真实大约 6%。
  //          这是本轨唯一一处为迁就规范而改长度的地方，别学它。
  //
  // 这批的三张参照图，标注与照片整体错位一格。判据不是"我觉得像"，是三条能复核的硬事实：
  //   ① 布局方向：第一张的弹匣插在扳机护圈**之后**（无托），第二张在握把**之前**（常规）。
  //      用 工具/_gun_mask.js 把照片打成字符图量的，不是肉眼猜。
  //   ② 游戏自己的 MECH 表：`cf05:'bullpup-smg'`、`evo3:'smg-carbine'`、`p90:'bullpup-topmag'`。
  //      三张图的布局与这三个机构一一对上，与用户标注（野牛=螺旋弹筒、MAC-10=圆筒机匣）都对不上。
  //   ③ 弹匣深度与配置的弹容量同向：第一张那个深到占图高 68% 的直匣 ⇒ cf05.mag=50；
  //      第二张较短的前倾匣 ⇒ evo3.mag=30。
  //   第三张是 FN P90 更直接：顶部横置半透明弹匣 + 机身两个拇指孔，而 p90 本来就是未建模的独立 ID。
  //   ⇒ 结论：三张图归 cf05 / evo3 / p90。**ppbizon 与 mac10 本轮没有拿到图，仍是 legacy**，
  //     宁可不画也不拿错位的图凑数。
  //
  // 标尺独立校核（与总长无关的件径，三张各自成立；折毫米一律按真实 29.4mm/单位折，
  // 不用被拉长过的 p90 标尺）：
  //   p90   照片长高比 2.930；按公开全长 500mm 折回总高 171mm、机匣主体高 118mm，
  //         与顶置弹匣的实物相符 ⇒ 500mm 站得住，规范下限 18 那一侧才是问题所在。
  //   evo3  枪口段外径 0.57 单位 ≈ 17mm（9mm 枪口段合理带 15~20mm）；骨架托展开高 103mm。
  //   cf05  弹匣外露 6.0 单位 = 176mm（50 发 5.8×21 双排直匣的合理带）；
  //         全枪长高比 2.111 与照片实测 2.111 一致（这是自解出来的长度，只能自洽、不算查证）。
  //   复核命令：node 美术重构-工作区/工具/_gun_mask.js <图名>（把照片打成字符图）
  //             node 美术重构-工作区/工具/_gun_spec.js <id>（逐件反算毫米）
  // ============================================================

  // ---------- CF05：05 式无托紧凑型，直长匣插在握把之后 ----------
  // 目标格（格心 ∪ 整格，70 格）：
  //   行  7：10-11      行  6：10-11      行  5：9-11       行  4：9-11
  //   行  3：col 0, 9-11   行  2：cols 0-1, 9-11, 13   行  1：cols 0-1, 9-14, 16
  //   行  0：cols 0-18, 20-21   行 -1：cols 6-19   行 -2：cols 6-8, 15, 17-18
  //   洞：(12,2) —— 护圈里那一格真空。
  //   无托的读法：col 0 是托尾，**cols 9-11 那根垂到行 7 的深匣在 cols 12-14 扳机组的后面**。
  //   前伸的细管（cols 20-21 只有行 0）是枪口，行 -2 的 cols 17,18 是准星座。
  const cf05Body = (S) => {
    // —— 行 0 脊线：无托机身通长，枪口单独两格 ——
    S.r(M.noir, 0, 0, 19.0, 1);                                // 机身（托/机匣/护木一体）→ cols 0-18 / 行 0
    S.l(M.barrel.base, 19.6, 0, 21.4, 0);                      // 裸露枪口 → cols 20,21 / 行 0（col 19 是空的）
    // —— 机匣顶与两端瞄具 ——
    S.r(M.noir, 6, -1, 14.0, 1);                               // 上缘通长 → cols 6-19 / 行 -1
    S.r(M.noir, 6, -2, 3.0, 1);                                // 尾部照门座 → cols 6-8 / 行 -2
    S.r(M.noir, 15, -2, 1.0, 1);                               // 抛壳盖后缘 → col 15 / 行 -2
    S.r(M.noir, 17, -2, 2.0, 1);                               // 准星座 → cols 17,18 / 行 -2
    // —— 托尾：cols 0-1 三行，行 1 的 col 1 是托里的镂空 ——
    S.r(M.polyDark, 0, 1, 1.0, 3);                             // 托尾板 → col 0 / 行 1-3
    S.r(M.polyDark, 1, 1, 1.0, 2);                             // 托背下沿 → col 1 / 行 1-2
    // —— 扳机组与深弹匣（弹匣在扳机**之后** = 无托）——
    S.r(M.noir, 9, 1, 6.0, 1);                                  // 机匣下沿 + 护圈 → cols 9-14 / 行 1
    S.r(M.noir, 16, 1, 1.0, 1);                                 // 前握持凸台 → col 16 / 行 1
    S.r(M.noir, 13, 2, 1.0, 1);                                 // 护圈前缘 → col 13 / 行 2
    S.r(M.polyDark, 9, 2, 3.0, 4);                             // 弹匣上段 → cols 9-11 / 行 2-5
    S.r(M.polyDark, 10, 6, 2.0, 2);                            // 弹匣底板 → cols 10,11 / 行 6-7
    // —— 检视尺度细节（全部落在已点亮的格上）——
    S.l(M.noir.lo, 7.4, -1.4, 14.4, -1.4, true);               // 机匣顶防滑纹（检视）
    S.l(M.poly.lo, 10.4, 2.4, 10.4, 5.4, true);                // 匣身纵筋（检视）
    S.l(M.barrel.hi, 12.6, 1.4, 12.6, 1.9, true);              // 扳机（护圈洞在 (12,2)，扳机落行 1）
    S.d(M.barrel.hi, 8.4, -0.6, 1, true);                      // 拉机柄
    S.l(M.blued.lo, 21.4, -0.4, 21.4, 0.4, true);              // 枪口槽
  };
  const cf05Silhouette = 单向('cf05', cf05Body);

  // ---------- EVO-III：常规布局，前倾直匣 + 三角骨架折叠托 ----------
  // 目标格（格心 ∪ 整格，70 格）：
  //   行  5：12-13   行  4：12-13   行  3：cols 6-8, 11-13   行  2：cols 1-2, 6-13
  //   行  1：col 0, cols 2-4, 6-13  行  0：cols 0-19（通长）
  //   行 -1：col 0, cols 5-17       行 -2：cols 7-8, 16-17
  //   洞：骨架托镂空 (1,-1)(2,-1)(3,-1)(4,-1)、托尾缝 (1,1)
  //   与 cf05 最好分的地方：**弹匣（cols 11-13）在握把（cols 6-8）之前**，且托是空心的三角框。
  const evo3Body = (S) => {
    // —— 行 0 脊线：托 → 机匣 → 护木 → 枪口，通长一条 ——
    S.r(M.noir, 0, 0, 20.0, 1);                                // → cols 0-19 / 行 0
    // —— 机匣顶导轨与两端瞄具 ——
    S.r(M.noir, 5, -1, 13.0, 1);                               // 平顶导轨 → cols 5-17 / 行 -1
    S.r(M.noir, 0, -1, 1.0, 1);                                // 托尾上角 → col 0 / 行 -1
    S.r(M.noir, 7, -2, 2.0, 1);                                // 折叠照门 → cols 7,8 / 行 -2
    S.r(M.noir, 16, -2, 2.0, 1);                               // 折叠准星 → cols 16,17 / 行 -2
    // —— 三角骨架托：col 0 竖板 + 行 1 撑杆 + 行 2 下缘，行 -1 的 cols 1-4 是空的 ——
    S.r(M.polyDark, 0, 1, 1.0, 1);                             // 托尾板下缘 → col 0 / 行 1
    S.r(M.noir, 2, 1, 3.0, 1);                                 // 托撑杆 → cols 2-4 / 行 1
    S.r(M.noir, 1, 2, 2.0, 1);                                 // 托下缘 → cols 1,2 / 行 2
    // —— 机匣下方、握把与弹匣 ——
    S.r(M.noir, 6, 1, 8.0, 1);                                 // 机匣底 + 护圈 + 匣井 → cols 6-13 / 行 1
    S.r(M.noir, 6, 2, 8.0, 1);                                 // → cols 6-13 / 行 2
    S.r(M.polyDark, 6, 3, 3.0, 1);                             // 握把 → cols 6-8 / 行 3
    S.r(M.polyDark, 11, 3, 3.0, 1);                            // 弹匣上段 → cols 11-13 / 行 3
    S.r(M.polyDark, 12, 4, 2.0, 2);                            // 弹匣 → cols 12,13 / 行 4-5
    // —— 检视尺度细节 ——
    S.l(M.noir.lo, 8.4, -1.4, 15.4, -1.4, true);               // 导轨齿（检视）
    S.l(M.poly.lo, 13.4, 3.4, 13.4, 4.4, true);                // 匣身纵筋（检视）
    S.l(M.barrel.hi, 9.6, 1.4, 9.6, 2.4, true);                // 扳机
    S.d(M.barrel.hi, 10.4, -0.6, 1, true);                     // 拉机柄
    S.l(M.polyDark.hi, 2.4, 1.4, 4.4, 1.4, true);              // 托撑杆高光（检视）
  };
