    S.l(M.polyDark.lo, 11.4, 2.6, 12.4, 4.4, true);             // 握把防滑纹（行 3-4）
    S.l(M.blued.lo, 33.4, -0.4, 33.4, 0.4, true);               // 枪口环（只占行 0，行 -1 到 col 30 就断了）
