    S.r(M.noir, 17, -2, 2.0, 1);                                // 照门座 → cols 17,18 / 行 -2
    S.r(M.noir, 33, -2, 1.0, 1);                                // 准星座 → col 33 / 行 -2
    S.r(M.walnut, 0, 1, 2.0, 1);                                // 托尾 → cols 0,1 / 行 1
    S.r(M.walnut, 5, 1, 5.0, 1);                                // 托颈 → cols 5-9 / 行 1
    S.r(M.noir, 11, 1, 8.0, 1);                                 // 机匣底 + 护圈 + 匣井 → cols 11-18 / 行 1
    S.r(M.noir, 27, 1, 5.0, 1);                                 // 脚架（上段）→ cols 27-31 / 行 1
    S.r(M.walnut, 0, 2, 5.0, 1);                                // 木托 → cols 0-4 / 行 2
    S.r(M.noir, 8, 2, 3.0, 1);                                  // 扳机组 → cols 8-10 / 行 2
    S.r(M.noir, 14, 2, 5.0, 1);                                 // 弹匣上段 → cols 14-18 / 行 2
    S.r(M.noir, 27, 2, 5.0, 1);                                 // 脚架 → cols 27-31 / 行 2
