  // ---------- 加特林：一束转管 + 提把 + 后握把，整支只有两格高 ----------
  // 目标格（格心 ∪ 整格，86 格）：
  //   行  3：col 7         行  2：cols 7-11         行  1：cols 2-12
  //   行  0：cols 0-1, 3-27   行 -1：cols 0-1, 3-27   行 -2：col 0, 2-10   行 -3：cols 0-1, 8-10
  //   洞：(1,-2)(2,-1)(2,0)(7,-3)
  //   行 -1 与行 0 两条通长 = **转管束**（六根管并在一起只占两格高）；
  //   行 -2/-3 的 cols 2-10 是提把，行 1-3 的 cols 7-12 是挂在机匣下方的弹链箱。
  //   len=27.2（800mm）取 M134 常引值，**中置信** —— 这张照片是虚构风格重绘，
  //   没有可查的权威全长，只能按转管束外径旁证。
  const gatlingBody = (S) => {
    S.r(M.noir, 0, 0, 2.0, 1);                                  // 机匣尾 → cols 0,1 / 行 0
    S.r(M.noir, 3, 0, 25.0, 1);                                 // 转管束下排 → cols 3-27 / 行 0
    S.r(M.noir, 0, -1, 2.0, 1);                                 // 机匣尾上沿 → cols 0,1 / 行 -1
    S.r(M.noir, 3, -1, 25.0, 1);                                // 转管束上排 → cols 3-27 / 行 -1
    S.r(M.noir, 0, -2, 1.0, 1);                                 // 提把立杆 → col 0 / 行 -2
    S.r(M.noir, 2, -2, 9.0, 1);                                 // 提把横杆 → cols 2-10 / 行 -2
    S.r(M.noir, 0, -3, 2.0, 1);                                 // 后握把上端 → cols 0,1 / 行 -3
    S.r(M.noir, 8, -3, 3.0, 1);                                 // 提把握柄 → cols 8-10 / 行 -3
    S.r(M.noir, 2, 1, 11.0, 1);                                 // 机匣底 + 弹链箱上沿 → cols 2-12 / 行 1
    S.r(M.noir, 7, 2, 5.0, 1);                                  // 弹链箱 → cols 7-11 / 行 2
    S.r(M.noir, 7, 3, 1.0, 1);                                  // 弹链箱底 → col 7 / 行 3
    S.l(M.noir.lo, 4.4, -0.4, 26.4, -0.4, true);                // 管束之间的分缝（检视）
    for (let i = 0; i < 4; i++) S.l(M.noir.hi, 6.4 + i * 5.0, -1.4, 6.4 + i * 5.0, 0.4, true);     // 固定箍环（检视）
    S.l(M.noir.hi, 3.4, -2.4, 9.4, -2.4, true);                 // 提把高光（检视）
    S.l(M.poly.lo, 0.4, -0.4, 0.4, 0.4, true);                  // 后握把纹（检视，只占行 0）
  };
  const gatlingSilhouette = 单向('gatling', gatlingBody);





  // ---------- P90：顶置半透明弹匣 + 两个拇指孔的无托 ----------
  // **长度是妥协来的，先说清楚**：P90 公开全长 500mm ÷ 29.4 = 17.0 单位，
  // 低于战斗尺度规范 combat.gunLenRange 的下限 18。用户 2026-09-30 选定
  // 「把 p90 拉长到 18」⇒ 这一把的标尺变成 500/18 = 27.8mm/单位（其余 27 把仍是 29.4），
  // 整支比真实尺寸放大约 6%。代价如实记在这里：p90 与别的枪并排看会偏长半格。
  // 目标格（格心 ∪ 整格，76 格，按 len=18 重出）：
  //   行  2：cols 5-14      行  1：cols 0-6, 9-11, 14-16   行  0：cols 0-6, 9-17
  //   行 -1：cols 0-16      行 -2：cols 0-11, 15-16        行 -3：cols 11-16
  //   洞：后拇指孔 (7,0)(8,0)(7,1)(8,1)、前手指孔 (12,1)(13,1)、
  //       弹匣被抬起来那道缝 (12,-2)(13,-2)(14,-2)
  //   这两排洞就是这支枪的身份证，一个都不能涂实。
  const p90Body = (S) => {
    // —— 行 0 脊线：托 → 机匣 → 枪口（P90 的枪口几乎不出机身）——
    S.r(M.noir, 0, 0, 7.0, 1);                                  // 机身尾段 → cols 0-6 / 行 0
    S.r(M.noir, 9, 0, 9.0, 1);                                  // 机匣前段 + 枪口 → cols 9-17 / 行 0
    // —— 机匣顶与顶置弹匣（行 -2 在 cols 12-14 留空 = 弹匣被镜桥抬起来那道缝）——
    S.r(M.noir, 0, -1, 17.0, 1);                                // 机匣顶通长 → cols 0-16 / 行 -1
    S.r(M.noir, 0, -2, 12.0, 1);                                // 机匣尾脊 → cols 0-11 / 行 -2
    S.r(M.polyDark, 15, -2, 2.0, 1);                            // 弹匣前端 → cols 15,16 / 行 -2
    S.r(M.polyDark, 11, -3, 6.0, 1);                            // 弹匣顶 → cols 11-16 / 行 -3
    // —— 无托的两个握持孔：行 1、行 2 被洞切成三段 ——
    S.r(M.noir, 0, 1, 7.0, 1);                                  // 机匣尾下沿 → cols 0-6 / 行 1
    S.r(M.noir, 9, 1, 3.0, 1);                                  // 握持桥 → cols 9-11 / 行 1
    S.r(M.noir, 14, 1, 3.0, 1);                                 // 前段下沿 → cols 14-16 / 行 1
    S.r(M.noir, 5, 2, 10.0, 1);                                 // 两孔下沿连成一条 → cols 5-14 / 行 2
    // —— 检视尺度细节（全部落在已点亮的格上）——
    S.l(M.glass.hi, 11.4, -2.6, 15.4, -2.6, true);              // 半透明匣里看得见的弹排
    S.l(M.noir.lo, 1.4, -1.4, 9.4, -1.4, true);                 // 机匣顶防滑纹（检视）
    S.l(M.barrel.hi, 10.6, 1.1, 10.6, 1.6, true);               // 扳机（后拇指孔在 cols 7,8）
    S.d(M.noir.hi, 10.4, -0.6, 1, true);                        // 拉机柄
    S.l(M.poly.lo, 15.4, 1.1, 15.4, 1.4, true);                 // 前手指孔前缘（检视，只落行 1）
  };
  const p90Silhouette = 单向('p90', p90Body);

  // ppbizon / mac10 本轮**没有拿到对应的参照图**（用户给的三张经核是 cf05 / evo3 / p90），
