        flash: { shape: 'star', petals: 5, fwd: 2.8, side: 0.72, ball: 0.52, tail: 0.13, jitter: 0.26, win: [0.012, 0.34] },
        smoke: { puff: 2.9, rise: -8, drift: 15, life: 0.34, at: 0.16, alpha: 0.4 },
